/* =========================================================================
   Section 2: Utilities, RNG, formatting
   ========================================================================= */
/** @type {RShape} */
const R = {
  s: 12345,
  next(){ let t = (this.s = (this.s + 0x6D2B79F5) | 0); t = Math.imul(t ^ (t>>>15), 1|t); t = (t + Math.imul(t ^ (t>>>7), 61|t)) ^ t; return ((t ^ (t>>>14))>>>0)/4294967296; },
  f(){ return this.next(); },
  int(a,b){ return a + Math.floor(this.next()*(b-a+1)); },
  range(a,b){ return a + this.next()*(b-a); },
  pick(a){ return a[Math.floor(this.next()*a.length)]; },
  chance(p){ return this.next() < p; },
  gauss(m,sd){ let u = 1-this.next(), v = this.next(); return m + sd*Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); },
  weighted(list, wf){ let tot = 0; const w = list.map(x=>{const v=Math.max(0,wf(x)); tot+=v; return v;}); if(tot<=0) return null;
    let r = this.next()*tot; for(let i=0;i<list.length;i++){ r -= w[i]; if(r<=0) return list[i]; } return list[list.length-1]; },
  pickN(a,n){ const c=a.slice(); const out=[]; while(c.length && out.length<n) out.push(c.splice(Math.floor(this.next()*c.length),1)[0]); return out; }
};
const clamp=(v,a,b)=>v<a?a:v>b?b:v;

function fmt(n, opt){
  opt = opt||{};
  if(n===null||n===undefined||isNaN(n)) return CUR()+'—';
  const neg = n<0; const abs = Math.abs(n); let s;
  if(abs>=1e12) s=(abs/1e12).toFixed(2)+'tr';
  else if(abs>=1e9) s=(abs/1e9).toFixed(2)+'bn';
  else if(abs>=1e6) s=(abs/1e6).toFixed(abs>=1e8?1:2)+'m';
  else if(abs>=1e4) s=(abs/1e3).toFixed(0)+'k';
  else if(abs>=1e3) s=(abs/1e3).toFixed(1)+'k';
  else s=Math.round(abs).toLocaleString();
  return (neg?'-':'')+(opt.sign&&!neg?'+':'')+CUR()+s;
}
const pct = (v,d) => (v*100).toFixed(d===undefined?1:d)+'%';
const dateLabel = t => 'Q'+((t%4)+1)+' '+(START_YEAR + Math.floor(t/4));
const START_YEAR = 2026;
function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
/* A folded explanation, the redesign's central move: the label is always there,
   the paragraph is not. It lives in core, not the ui, because both renderers
   write it — the single file's string screens and the app's React screens — and
   because core's own strips use it (the open stories on Overview). It was in the
   ui for one afternoon, and the module build caught it the moment a core strip
   called it: `foldHTML is not defined`, in a test that had nothing to do with
   folds. The single-file build hid the bug completely, which is the whole reason
   the modular build and its tests exist. */
function foldHTML(label, html){
  return '<details class="fold"><summary>'+esc(label)+'</summary><div>'+html+'</div></details>';
}
function bar(v, max, color){
  const p = clamp((v/max)*100, 0, 100);
  /* gfx: a bar is a picture of a number, and the visual audit counts it as one */
  return '<div class="bar gfx"><i style="width:'+p+'%;background:'+(color||'var(--acc)')+'"></i></div>';
}

/* =========================================================================
   Section 3: Game state
   ========================================================================= */
let S = null;          // live game state
/* The ui reads a save out of storage, but S is the core's to hold. In the
   single file both sides were in one scope and the assignment just worked; a
   module boundary makes that an error, which is the boundary doing its job. */
function setS(v){ S = v; return S; }
          // live game state
let UI = { tab:'overview', sub:'', bizSub:'ops', modal:null, lastGain:0, worldFocus:'', details:false };
let TX = [];           // this-turn transaction ledger lines

function blankState(){
  return {
    v:1, seed:1, city:'lagos', difficulty:'realistic', name:'', profile:'grad',
    turn:0, gameOver:null, startedAt:Date.now(),
    p:{ age:24, edu:'BSc', health:80, stress:30, happy:65, family:70, rep:40,
        skills:{finance:30,ops:30,hustle:30,network:30,tech:30},
        job:null, jobPerf:60, jobYears:0, married:false, kids:0, parents:2, partner:null },
    fin:{ cash:0, usdCash:0, debt:[], goods:[], budget:null, credit:62, overdrawn:0 },
    assets:[], biz:null, bizs:[], activeBiz:null, offers:[], informalIncome:0, cumInfl:1, creditCrunch:0,
    cast:[], threads:[], deals:[], rival:null, ambition:null, era:null, digest:[], stand:null, pegBudget:false,
    mkt:null, hist:[], journal:[], pending:[], flags:{}, cd:{}, seq:0, decisions:[], candidates:[],
    quarter:{ income:0, expense:0, bizProfit:0, invest:0, note:'' },
    house:[], houseCands:[],
    season:null,                   /* a fixed finish line — see Seasons, below */
    dealt:null,                    /* today's life, when the start was dealt: {day, draw} */
    why:{},                     /* dismissed "why this screen matters" hints */
    grp:{}                     /* collapsed card groups, per screen */
  };
}

function newGame(cfg){
  S = blankState();
  S.seed = cfg.seed || (Math.floor(Math.random()*1e9));
  R.s = S.seed|0;
  S.city = cfg.city || 'lagos';
  S.difficulty = cfg.difficulty || 'realistic';
  /* The adaptive tune is normally keyed to your own record, which is right for
     a solo run and wrong for a season: two people in the same season would get
     different worlds because one of them has played more. Measured spread was
     32.6% in shock intensity between a novice and a veteran — enough to decide
     a leaderboard on its own. So a season pins the tune to the untuned
     baseline for everybody. The tier still applies; only the adaptive
     component is held constant, and that is exactly the part that would have
     made the comparison meaningless. */
  S.tune = computeTune(cfg.season ? null : skillRating(ensureProfile()), S.difficulty);
  S._runLogged = false;
  S.name = (cfg.name||'You').trim() || 'You';
  const P = PROFILES.find(p=>p.id===cfg.profile) || PROFILES[0];
  S.profile = P.id;
  const c = CITIES.find(x=>x.id===S.city);
  const scale = c.payMult;
  S.p.age = P.age; S.p.edu = P.edu;
  S.p.skills = Object.assign({}, P.skills);
  S.p.health = P.start.health; S.p.stress = P.start.stress; S.p.happy = P.start.happy;
  S.p.family = P.start.family; S.p.rep = P.start.rep;
  S.fin.cash = Math.round(P.cash * (0.6 + 0.4*c.payMult));
  S.fin.usdCash = P.usd;
  if(P.salary>0){
    S.p.job = { title:P.jobTitle, monthly:Math.round(P.salary*scale), industry:'Corporate' };
  }
  if(P.debt>0){ S.fin.debt.push({id:'d1', name:'Personal loan', bal:P.debt, rate:0.09, minPay:Math.round(P.debt*0.12), kind:'bank'}); }
  S.informalIncome = P.informalIncome ? Math.round(P.informalIncome*scale) : 0;
  S.fin.budget = defaultBudget(P, c);
  S.budgetInfl = 1;
  S.mkt = initMarket(c);
  S.hist = [];
  S.journal = [];
  log('start','You begin in '+c.name+'. Age '+P.age+'. '+P.blurb, 'begin');
  if(P.debt>0) log('start','You carry an existing personal loan of '+fmt(P.debt)+'.', 'warn');
  TX = [];
  S.cast = buildCast();
  S.threads = []; S.deals = []; S.active = []; S.digest = [];
  S.era = initEra();
  S.rival = genRival();
  S.ambition = {id:(cfg.ambition || 'free'), chosen:!!cfg.ambition};
  S.stand = {family:60, industry:35, community:50, state:40, street:30};
  S.pegBudget = false;
  S._startAge = S.p.age;
  TX = [];
  refreshDeals();
  S.vignette = makeVignette();
  S.candidates = [genCandidate(0), genCandidate(0), genCandidate(1)];
  UI.tab='overview'; UI.bizSub='ops'; UI.modal=null;
  recompute();
  snapshot();
  if(S.difficulty!=='hardcore') save('auto');
  return S;
}

/* ── Today's life: a start that is dealt, not chosen ──────────────────────
   The five profiles say who you are; a draw says what you were born into, and
   nobody picks that. The deal is a function of the date in Lagos, so everyone
   who starts today is dealt the same life, and it cannot be re-dealt: the only
   way to get another is to come back tomorrow. That is what makes it worth a
   screenshot - a deal you could reroll is a slot machine.

   Every draw is unequal and none is a free win: each one carries the thing it
   costs you, the way a loan from day one also teaches you to count every naira.
   The amounts are at the price level a run starts on (cumInfl 1). */
const DRAWS = [
  {id:'nepo', name:'Daddy’s name opens doors',
   up:'₦2.5m from home, and a network that returns calls',
   down:'everyone assumes it was Daddy, and you never learned to hustle',
   fx:{cash:2500000, skills:{network:15, hustle:-12}, p:{rep:-6}, stand:{industry:10}}},
  {id:'lapo', name:'A microfinance loan from day one',
   up:'you learned to count every naira, and to move fast',
   down:'₦450k owed at 7% a quarter before your first payslip',
   fx:{debt:{bal:450000, rate:0.07, minPay:75000, name:'Microfinance loan'}, skills:{hustle:15, finance:10}, p:{stress:6}}},
  {id:'ada', name:'First child, family breadwinner',
   up:'the family stands behind you, and so does their network',
   down:'the family budget is yours to carry, and it is bigger',
   fx:{skills:{network:8}, p:{family:12, stress:8}, stand:{family:15}, familyBudget:1.6}},
  {id:'houston', name:'An uncle in Houston',
   up:'$2,000 sent home for your start',
   down:'the remittance runs both ways: home now expects its share',
   fx:{usd:2000, p:{stress:5}, familyBudget:1.25}},
  {id:'mushin', name:'Raised in Mushin, schooled by the street',
   up:'hustle and a street that knows your name',
   down:'banks do not know you, and some rooms close when you walk in',
   fx:{skills:{hustle:18, network:10}, p:{rep:-8}, stand:{street:20}, credit:-12}},
  {id:'fellowship', name:'Your mother runs the women’s fellowship',
   up:'a congregation that vouches for you',
   down:'tithe and harvest levies from the first month',
   fx:{skills:{network:12}, p:{happy:5}, stand:{community:20}, giving:15000}},
];
/* The date the deal belongs to: the calendar day in Lagos (UTC+1, no DST). */
function todayKey(now){
  return new Date((now === undefined ? Date.now() : now) + 3600000).toISOString().slice(0, 10);
}
/* FNV-1a over the day, so the same day always deals the same life on every
   device and in both runtimes, with no server and no clock but the player's. */
function dayHash(key){
  let h = 0x811c9dc5;
  const t = 'ledger-day:' + key;
  for(let i = 0; i < t.length; i++){ h ^= t.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h >>> 0;
}
/** @param {string} [key] */
function todaysLife(key){
  const day = key || todayKey();
  const h = dayHash(day);
  return { day:day, seed:(h % 999999937) + 1,
           profile:PROFILES[h % PROFILES.length].id,
           draw:DRAWS[(h >>> 8) % DRAWS.length].id,
           city:'lagos', difficulty:'realistic' };
}
/* Applied once, straight after newGame, and it draws nothing from the seeded
   stream - so a dealt run is the same world as an undealt run on the same seed,
   plus the circumstance. */
function applyDraw(id){
  const d = DRAWS.find(function(x){ return x.id === id; });
  if(!d) return null;
  const f = d.fx;
  if(f.cash) S.fin.cash += f.cash;
  if(f.usd) S.fin.usdCash += f.usd;
  if(f.debt) S.fin.debt.push({id:'draw', name:f.debt.name, bal:f.debt.bal, rate:f.debt.rate, minPay:f.debt.minPay, kind:'bank'});
  Object.keys(f.skills || {}).forEach(function(k){ S.p.skills[k] = clamp(S.p.skills[k] + f.skills[k], 0, 100); });
  Object.keys(f.p || {}).forEach(function(k){ S.p[k] = clamp(S.p[k] + f.p[k], 0, 100); });
  Object.keys(f.stand || {}).forEach(function(k){ S.stand[k] = clamp(S.stand[k] + f.stand[k], 0, 100); });
  if(f.credit) S.fin.credit = clamp(S.fin.credit + f.credit, 0, 100);
  if(f.familyBudget) S.fin.budget.family = Math.round(S.fin.budget.family * f.familyBudget);
  if(f.giving) S.fin.budget.giving = f.giving;
  log('start', 'Dealt, not chosen: '+d.name+'. '+d.up.charAt(0).toUpperCase()+d.up.slice(1)+'; '+d.down+'.', 'begin');
  recompute();
  return d;
}

function defaultBudget(P,c){
  const nd = needs();
  const inc = Math.max(0, (P.salary*c.payMult) + (P.informalIncome||0)*c.payMult);
  const total = nd.housing+nd.food+nd.transport+nd.lifestyle+nd.family;
  // how much of a decent life your income actually covers (0.92 leaves a little room to breathe)
  const scale = inc>0 ? clamp((inc*0.92)/total, 0.5, 1.15) : 0.62;
  return {
    housing:   Math.round(nd.housing*scale),
    food:      Math.round(nd.food*Math.min(1, scale*1.25)),   // food is the last thing cut
    transport: Math.round(nd.transport*scale),
    lifestyle: Math.round(nd.lifestyle*scale*0.85),
    family:    Math.round(nd.family*Math.min(1, scale*1.2)),
    learning:  0,
    giving:    0
  };
}

let _dCache = null;
/* The tier sets the character of the run; the tuning leans on it. A veteran on
   Realistic is not playing the same game as a newcomer on Realistic, and neither
   of them is playing Hardcore - the multipliers are capped well below that gap. */
function D(){
  const base = DIFFS[S.difficulty] || DIFFS.realistic;
  const t = S.tune;
  if(!t || typeof t.shock!=='number') return base;      // old saves, or before tuning exists
  if(_dCache && _dCache.base===base && _dCache.t===t) return _dCache.v;
  const v = Object.assign({}, base, {
    shock: base.shock*t.shock, fail: base.fail*t.fail,
    infl:  base.infl*t.infl,   pay:  base.pay*t.pay,
    talent: t.talent||1, heat: t.heat||1, tuned:true
  });
  _dCache = {base:base, t:t, v:v};
  return v;
}
/** @type {DIFFSShape4} */
const DIFFS = {
  apprentice:{key:'apprentice', name:'Apprentice', shock:0.55, infl:0.68, showOdds:true,  coaching:true,  saveScum:true,  pay:1.12, fail:0.72,
    desc:'Softer shocks and every decision explains the real-world principle. Learn the machine.'},
  realistic: {key:'realistic',  name:'Realistic',  shock:1.45, infl:1.18, showOdds:false, coaching:false, saveScum:true,  pay:0.93, fail:1.32,
    desc:'The intended experience. Probabilities are honest. Save and load freely.'},
  hardcore:  {key:'hardcore',   name:'Hardcore',   shock:1.40, infl:1.22, showOdds:false, coaching:false, saveScum:false, pay:0.92, fail:1.35,
    desc:'One autosave slot, no rewinds, harsher macro. Bankruptcy ends the run.'},
  /* The three tiers above are not the ceiling. They are the point at which most
     people stop. These unlock as your record proves you can take more, and the
     adaptive tier below has no ceiling at all. */
  relentless:{key:'relentless', name:'Relentless', shock:1.72, infl:1.24, showOdds:false, coaching:false, saveScum:false, pay:0.88, fail:1.48, need:60,
    desc:'The macro turns on you and stays turned. Good quarters are still possible; they are no longer the default. Talent gets expensive and credit gets personal.'},
  brutal:    {key:'brutal',     name:'Brutal',     shock:1.72, infl:1.32, showOdds:false, coaching:false, saveScum:false, pay:0.82, fail:1.65, need:72,
    desc:'Two bad decisions in a row now end runs. Competitors price against you, staff leave for less than you would believe, and the state notices you.'},
  merciless: {key:'merciless',  name:'Merciless',  shock:1.90, infl:1.40, showOdds:false, coaching:false, saveScum:false, pay:0.72, fail:2.05, need:84,
    desc:'The game is no longer pretending to be fair. You are playing against an economy that has read your record and adjusted accordingly.'},
  adaptive:  {key:'adaptive',   name:'Adaptive',   shock:1.45, infl:1.18, showOdds:false, coaching:false, saveScum:true,  pay:0.93, fail:1.32, adaptive:true,
    desc:'No fixed setting. The game reads your record and sets the difficulty itself, then keeps raising it for as long as you keep proving you can take it. There is no ceiling — if Hardcore stopped being hard, this is the one you want.'}
};
/* A tier gated on your record. The base three are always open; the ones above
   Hardcore have to be earned, and the field is not a boast — it is what the
   game actually checks before it will let you select them. */
function tierUnlocked(k){
  const d = DIFFS[k]; if(!d) return false;
  if(!d.need) return true;
  const sk = skillRating(ensureProfile());
  return sk !== null && sk >= d.need;
}
function tierLockNote(k){
  const d = DIFFS[k]; if(!d || !d.need) return '';
  const sk = skillRating(ensureProfile());
  return 'Locked — reach an experience rating of '+d.need+' to unlock it'+
         (sk===null ? '.' : '. You are at '+Math.round(sk)+'.');
}

/* =========================================================================
   Section 4: Macro economy
   ========================================================================= */
function initMarket(c){
  return {
    infl:c.infl, inflTarget:c.infl, usd:c.fxBase, usdPrev:c.fxBase, mpr:c.infl+0.06,
    oil:78, sentiment:52, power:44, gdp:0.031, demand:1.00, quarterShock:0,
    news:[], fxShockTurn:-99
  };
}

/** @type {POLICY_EVENTSShape[]} */
const POLICY_EVENTS = [
  {id:'fuel',   w:1.0, cond:m=>true, head:'Fuel subsidy removed overnight',
   text:'Pump price triples before dawn. Transport, food and diesel repriced by lunchtime.',
   fx:m=>{ m.infl += 0.055*D().shock; m.sentiment -= 12; m.demand -= 0.05; }},
  {id:'deval',  w:1.4, cond:m=>true, head:'Currency devalued at the official window',
   text:'The central bank unification lands. Importers reprice everything within a week.',
   fx:m=>{ const s=(0.14+R.f()*0.26)*D().shock; m.usd *= (1+s); m.fxShockTurn = S.turn; m.infl += 0.035*D().shock; m.sentiment -= 8; return 'FX move: +'+(s*100).toFixed(0)+'%'; }},
  {id:'naira',  w:0.7, cond:m=>true, head:'Cash redesign / naira scarcity',
   text:'New notes, no notes. POS operators become the most powerful people in the country for six weeks.',
   fx:m=>{ m.demand -= 0.12; m.sentiment -= 6; }},
  {id:'rate',   w:1.2, cond:m=>true, head:'Monetary policy committee hikes aggressively',
   text:'Borrowing gets expensive. Fixed income suddenly pays; equities and property stop moving.',
   fx:m=>{ m.mpr += 0.05*D().shock; m.demand -= 0.04; m.sentiment -= 4; }},
  {id:'ease',   w:0.9, cond:m=>m.mpr>0.10, head:'Central bank begins an easing cycle',
   text:'Credit loosens. Cheap money returns and risk assets breathe again.',
   fx:m=>{ m.mpr = Math.max(0.05, m.mpr-0.045); m.demand += 0.05; m.sentiment += 7; }},
  {id:'oil',    w:0.9, cond:m=>true, head:'Oil price collapse',
   text:'The budget gaps widen, the currency wobbles, and government contracts stop paying.',
   fx:m=>{ m.oil = clamp(m.oil*0.62, 28, 130); m.usd *= 1.07; m.sentiment -= 9; m.gdp -= 0.012; }},
  {id:'boom',   w:0.8, cond:m=>true, head:'Foreign investment returns',
   text:'Capital floods in. Valuations, land prices and confidence move together.',
   fx:m=>{ m.usd *= 0.94; m.sentiment += 12; m.demand += 0.08; m.gdp += 0.008; }},
  {id:'grid',   w:1.1, cond:m=>true, head:'National grid collapses — again',
   text:'Eleven days of darkness. Diesel sellers and solar installers have a very good quarter.',
   fx:m=>{ m.power = clamp(m.power-22, 5, 95); m.demand -= 0.03; m.infl += 0.008; }},
  {id:'gridup', w:0.7, cond:m=>m.power<70, head:'Power supply improves unexpectedly',
   text:'A new independent grid deal lands. Businesses quietly stop budgeting for diesel.',
   fx:m=>{ m.power = clamp(m.power+26, 5, 98); m.demand += 0.03; }},
  {id:'tax',    w:0.8, cond:m=>true, head:'New tax regime takes effect',
   text:'Withholding, VAT and levies get restructured. Compliance costs go up for everyone formal.',
   fx:m=>{ if(S.biz && S.biz.formal){ S.biz.taxLoad = (S.biz.taxLoad||0.05)+0.02; } m.sentiment -= 5; }},
  {id:'bank',   w:0.5, cond:m=>true, head:'Bank recapitalisation directive',
   text:'Lenders must raise capital. Credit to small business dries up for two quarters.',
   fx:m=>{ S.creditCrunch = 2; m.demand -= 0.03; }},
  {id:'insec',  w:0.6, cond:m=>true, head:'Security incident spooks investors',
   text:'A high-profile incident dominates the news. Logistics routes lengthen, insurance rises.',
   fx:m=>{ m.sentiment -= 10; m.demand -= 0.05; }},
];

function stepMarket(){
  const m = S.mkt, d = D(), c = CITIES.find(x=>x.id===S.city);
  m.usdPrev = m.usd;
  // inflation: target mean-reverts to this economy's structural rate, then inflation chases the target
  const structural = clamp(c.infl * d.infl + eraFx('infl'), 0.008, 0.75);
  m.inflTarget = clamp(m.inflTarget + (structural - m.inflTarget)*0.07 + R.gauss(0, 0.010), 0.010, 0.75);
  m.infl = clamp(m.infl + (m.inflTarget - m.infl)*0.25 + R.gauss(0,0.012)*d.shock, 0.006, 0.95);
  // fx: purchasing power parity drift + occasional discrete devaluation
  const drift = (Math.max(0, m.infl - 0.035)/4) * 0.55;
  m.usd = m.usd * (1 + drift + R.gauss(0, 0.011)*d.shock);
  if(R.chance(0.040*d.shock)){
    const s = (0.10 + R.f()*0.24) * d.shock;
    m.usd *= (1+s); m.fxShockTurn = S.turn;
    pushNews('Sudden devaluation: '+c.fxName+' +'+(s*100).toFixed(0)+'%', 'bad');
    log('macro','Discrete devaluation: '+c.fxName+' moved +'+(s*100).toFixed(0)+'% inside a week. Importers repriced before the news cycle did.','macro');
  }
  // rates track inflation with a real policy premium
  m.mpr = clamp(m.mpr + (Math.max(0.04, m.infl*0.85) - m.mpr)*0.28 + R.gauss(0,0.006), 0.02, 0.85);
  m.oil = clamp(m.oil + R.gauss(0, 6.5), 26, 145);
  m.sentiment = clamp(m.sentiment + R.gauss(0, 6)*d.shock + (50+eraFx('sent')-m.sentiment)*0.14, 3, 97);
  m.power = clamp(m.power + R.gauss(0, 7) + (45-m.power)*0.08, 3, 98);
  m.gdp = clamp(m.gdp + R.gauss(0,0.006), -0.03, 0.09);
  m.demand = clamp(1 + (m.sentiment-50)/230 + (m.gdp-0.03)*2.2 + R.gauss(0,0.028)*d.shock + eraFx('demand'), 0.34, 1.7);
  S.cumInfl = S.cumInfl * (1 + m.infl/4);
  if(S.biz && S.biz.locations>1) { /* prices pass through inflation via inflF */ }
  if(S.creditCrunch>0) S.creditCrunch--;
  // policy shock
  if(R.chance(0.16 * (1 + (eraFx('reg')?eraFx('reg')*0.5:0)))){
    const pool = POLICY_EVENTS.filter(e=>e.cond(m));
    const ev = R.weighted(pool, e=>e.w);
    if(ev){ const extra = ev.fx(m)||''; pushNews(ev.head, 'warn'); log('macro', ev.head+' — '+ev.text+(extra?' ('+extra+')':''), 'macro'); }
  }
  pushNews('Inflation '+pct(m.infl,1)+' · '+c.fxName+' '+Math.round(m.usd).toLocaleString()+' · MPR '+pct(m.mpr,1), 'neutral', true);
}
function pushNews(text, kind, quiet){
  S.mkt.news.unshift({t:text, k:kind, turn:S.turn});
  if(S.mkt.news.length>26) S.mkt.news.pop();
  if(!quiet){ /* headline shown in ticker */ }
}

/* =========================================================================
   Section 5: Derived state, personal finance, career
   ========================================================================= */
function CITY(){ return CITIES.find(c=>c.id===S.city) || CITIES[0]; }
function log(cat, text, kind){
  S.journal.unshift({turn:S.turn, date:dateLabel(S.turn), cat:cat, text:text, kind:kind||'neutral'});
  if(S.journal.length>320) S.journal.pop();
}
function tx(line){ TX.push(line); }

function assetValue(a){ return a.value||0; }
function goodsResale(){
  let v=0; const t=S.turn;
  (S.fin.goods||[]).forEach(g=>{
    const def = GOODS.find(x=>x.id===g.id); if(!def) return;
    const age = t - g.turn;
    if(def.life===0){ v += def.cost*0.15; return; }
    v += Math.max(0, def.cost * (1 - 0.055*age));
  });
  return v;
}
function bizValue(b){
  b = b || S.biz; if(!b) return 0;
  const T = BIZ.find(x=>x.id===b.type);
  const h = b.history.slice(-4);
  const avgP = h.length ? h.reduce((s,x)=>s+x.profit,0)/h.length : b.profit;
  const annP = avgP*4;
  const mult = (T.id==='tech'? 7.5 : 5.0) * (0.75 + (T.growth*2.2));
  let v = Math.max(0,b.cash) + (annP>0 ? annP*mult : annP*1.2) + (b.revenue*4)*(T.id==='tech'?1.6:0.6);
  if(!b.formal) v *= 0.82;              // informal businesses sell at a discount
  v *= (0.85 + outletAvgCond(b)/430);   // neglected units are worth less
  return Math.max(0, Math.round(v));
}
function bizValueTotal(){
  return bizList().reduce(function(a,b){ return a + bizValue(b); }, 0);
}
function debtTotal(){ return (S.fin.debt||[]).reduce((s,d)=>s+d.bal,0); }

function netWorth(){
  const a = (S.assets||[]).reduce((s,x)=>s+assetValue(x),0);
  return Math.round((S.fin.cash||0) + (S.fin.usdCash||0)*S.mkt.usd + a + goodsResale() + bizValueTotal() - debtTotal());
}
function salaryMonthly(){ return S.p.job ? S.p.job.monthly : 0; }
function informalMonthly(){ return (S.informalIncome||0) * (0.7 + R.f()*0.6); }
function goodsUpkeep(){ return (S.fin.goods||[]).reduce((s,g)=>{const d=GOODS.find(x=>x.id===g.id); return s + (d?d.upkeep:0);},0); }
function budgetMonthly(){ const b=S.fin.budget||{}; return (b.housing||0)+(b.food||0)+(b.transport||0)+(b.lifestyle||0)+(b.family||0)+(b.learning||0)+(b.giving||0); }
function passiveMonthly(){ // rents, dividends arriving as cash
  let v=0; (S.assets||[]).forEach(a=>{ const d=ASSETS.find(x=>x.id===a.id); if(d&&d.yieldQ) v += a.value*d.yieldQ/3; });
  return v;
}
function recompute(){
  S.der = {
    nw: netWorth(), assets:(S.assets||[]).reduce((s,x)=>s+assetValue(x),0),
    debt: debtTotal(), biz: bizValue(), goods: goodsResale(),
    income: salaryMonthly()*3 + (S.informalIncome||0)*3 + passiveMonthly()*3,
    spend: (budgetMonthly()+goodsUpkeep())*3
  };
  if(S.biz){ const T=BIZ.find(x=>x.id===S.biz.type); S.der.bizType=T; }
  return S.der;
}
function freedomIndex(){
  // 0-100: how much of your life you actually own
  const d = recompute();
  const monthlyPassive = (passiveMonthly() + (S.biz? Math.max(0,S.biz.profit)/3 : 0) + (S.assets||[]).reduce((s,a)=>{const x=ASSETS.find(y=>y.id===a.id); return s + (x&&!x.illiquid? a.value*(x.ret-0.02)/3 : 0);},0));
  const need = (budgetMonthly())||1;
  const coverage = clamp(monthlyPassive/need, 0, 3)/3;              // 0..1
  const wealth   = clamp(Math.log10(Math.max(1,d.nw)/1e6)/3.3, 0, 1); // 0 at 1m, 1 at ~2bn
  const life     = (S.p.health/100*0.28) + (S.p.happy/100*0.24) + (S.p.family/100*0.18) + (1-S.p.stress/100)*0.30;
  return Math.round((coverage*0.34 + wealth*0.36 + life*0.30)*100);
}

function needs(){
  const c = CITY(), p = S.p;
  const inf = S.cumInfl || 1;                              // a budget you never revisit stops working
  const fam   = 1 + (p.married?0.75:0) + p.kids*0.55;      // people actually in the house
  const oblig = 1 + (p.parents>0?0.55:0) + (p.kids*0.15);  // people you send money to
  return {
    housing:  Math.round(70000*c.rentMult*fam*0.75*inf),
    food:     Math.round(58000*fam*(0.55+0.45*c.rentMult)*inf),
    transport:Math.round(38000*fam*0.65*inf),
    lifestyle:Math.round(48000*fam*(0.6+0.4*c.rentMult)*inf),
    family:   Math.round(22000*oblig*(p.family<55?1.5:1)*inf)
  };
}

/* ---- one quarter of personal life ---- */
function stepPersonal(){
  const p = S.p, b = S.fin.budget, m = S.mkt, c = CITY(), d = D();
  const nd = needs();
  let income = 0, expense = 0;

  /* Sleep debt. The body collects what the calendar could not. It is repaid
     out of this quarter's discretionary hours at a limited rate, and until it
     clears, health and performance both suffer for it. */
  if(p.debt > 0){
    const repay = Math.min(p.debt, Math.round(hoursBudget()*0.30));
    p.debt  = Math.max(0, p.debt - repay);
    p.spent = Math.max(0, hoursSpent() - repay);
    const load = p.debt;
    p.health = clamp(p.health - 0.9 - load*0.045, 0, 100);
    p.stress = clamp(p.stress + 1.6 + load*0.05, 0, 100);
    if(p.jobPerf !== undefined) p.jobPerf = clamp(p.jobPerf - (1.2 + load*0.035), 5, 99);
    if(load > 60)  log('life','You are running on borrowed sleep and people can tell.','warn');
    if(load > 140) log('life','You have not properly slept in weeks. It is starting to cost you.','bad');
    if(load > 200 && R.chance(0.35)){
      p.health = clamp(p.health - 6, 0, 100);
      p.debt = Math.max(0, p.debt - 60);
      log('life','Your body made the decision for you. You lost a week to it.','bad');
    }
  }

  // ---- income
  if(p.job){
    const perfFactor = 0.85 + (p.jobPerf/100)*0.3;
    let sal = Math.round(p.job.monthly*3*perfFactor*d.pay);
    const tax = p.job.industry==='Informal' ? 0 : sal*0.11;
    income += sal - tax;
    if(tax>0) tx('PAYE & deductions −'+fmt(tax));
    tx('Salary ('+esc(p.job.title)+') +'+fmt(sal-tax));
    p.jobYears += 0.25;
    // annual review: wages chase inflation but usually lose the race
    if(S.turn % 4 === 3){
      const rise = m.infl*0.80 + 0.005 + R.gauss(0,0.02);
      const cap = Math.round(marketMonthly()*1.25);
      const next = Math.min(Math.round(p.job.monthly * (1 + Math.max(-0.05, rise))), cap);
      if(next > p.job.monthly) tx('Annual review +'+pct((next/p.job.monthly)-1,1));
      p.job.monthly = next;
    }
    // performance drifts toward a baseline set by skill + attention
    const target = 46 + p.skills.ops*0.22 + p.skills.tech*0.12 + (p.jobYears*3);
    p.jobPerf = clamp(p.jobPerf + (target - p.jobPerf)*0.18 + R.gauss(0,5), 5, 99);
    // redundancy risk
    if(p.jobPerf < 34 && R.chance(0.20*d.fail)) { fireFromJob(); }
  }
  if(S.informalIncome>0){
    const inf = Math.round(informalMonthly()*3);
    income += inf; tx('Informal trading income +'+fmt(inf));
  }
  if(p.partner && p.partner.income){
    income += p.partner.income*3; tx('Partner contributes +'+fmt(p.partner.income*3));
  }
  income += Math.round(passiveMonthly()*3);

  // ---- expenses
  const cats = ['housing','food','transport','lifestyle','family','learning','giving'];
  cats.forEach(k=>{ expense += (b[k]||0)*3; });
  const gu = goodsUpkeep()*3; expense += gu; if(gu>0) tx('Asset upkeep −'+fmt(gu));
  tx('Living costs −'+fmt(budgetMonthly()*3));

  // ---- needs satisfaction → stats
  const ratio = k => (b[k]||0)/Math.max(1,nd[k]);
  const foodR = clamp(ratio('food'),0,1.5), houseR = clamp(ratio('housing'),0,1.5);
  const foodPen = foodR>=1 ? (foodR-1)*22 : (foodR-1)*70;      // under-eating bites hard, over-eating barely helps
  const deprive = Math.max(-46, foodPen + (houseR-1)*20);      // neglect makes you ill; it does not, on its own, kill you
  const healthTarget = 80 + deprive - Math.max(0,p.age-42)*0.85 + clamp(staffSupport('health'), 0, 6);
  p.health = clamp(p.health + (healthTarget-p.health)*0.22 - Math.max(0,p.stress-62)/12 + R.gauss(0,1.2), 0, 100);
  p.happy  = clamp(p.happy + (clamp(ratio('lifestyle'),0,2)-1.0)*4 + (clamp(ratio('food'),0,1.5)-0.95)*2.5 - (p.stress-55)/90 + clamp(staffSupport('joy'),0,5) + R.gauss(0,1.6), 0, 100);
  const famGive = ratio('family');
  p.family = clamp(p.family + (clamp(famGive,0,2)-1.0)*11 - (p.kids*0.4) + (p.married?0.6:-0.2) + clamp(staffSupport('family'),0,6), 0, 100);
  const learnSpend = (b.learning||0)*3;
  if(learnSpend>60000){
    const gain = clamp(learnSpend/900000, 0.15, 2.2);
    const which = R.pick(['finance','ops','tech','network']);
    p.skills[which] = clamp(p.skills[which] + gain*R.range(1.6,3.4), 0, 100);
    tx('Learning: '+which+' skill improved');
  }
  if((b.giving||0)*3 > 40000){ p.rep = clamp(p.rep + 1.2, 0, 100); p.happy = clamp(p.happy+1.4,0,100); }
  const houseStatus = clamp(staffSupport('status'),0,4);
  if(houseStatus>0) p.rep = clamp(p.rep + houseStatus*0.10, 0, 100);   // a driver and a gate change how you are read

  // ---- stress
  const months = S.fin.cash / Math.max(1, budgetMonthly() + houseMonthlyYou());
  const moneyStress = months<0 ? 8 : months<1 ? 3.5 : months<3 ? 1.2 : 0;
  const bizStress = S.biz ? ((S.biz.profit<0?7:2) + Math.min(6, S.biz.staff.length*0.35)) : 0;
  const debtStress = debtTotal() > Math.max(1, income) ? 3.5 : (debtTotal()>0 ? 0.8 : 0);
  const relief = (clamp(ratio('lifestyle'),0,2)-1)*4 + (clamp(ratio('housing'),0,1.6)-1)*2.5;
  /* Your household: the house running is worth a great deal of quiet. It is also
     more people to manage, and a household in a bad mood is a thing you live inside. */
  const houseN      = (S.house||[]).length;
  const houseCalm   = clamp(staffSupport('calm'), 0, 13);
  const houseManage = houseN ? Math.min(7, 0.55*houseN + (S.house||[]).filter(function(h){ return (h.morale||60)<35; }).length*2.4) : 0;
  const stressTarget = 20 + moneyStress + bizStress + debtStress - relief - houseCalm + houseManage + (p.job?2:0) + (p.kids*1.2);
  p.stress = clamp(p.stress + (stressTarget-p.stress)*0.30 + R.gauss(0,2)*d.shock, 0, 100);
  if(p.stress>78){ p.health = clamp(p.health-1.6,0,100); if(R.chance(0.06)) log('health','Burnout is no longer theoretical. Your body is filing complaints.','bad'); }

  // ---- debt service
  (S.fin.debt||[]).forEach(dt=>{
    const interest = dt.bal*dt.rate;
    const pay = Math.min(dt.bal + interest, Math.max(dt.minPay, Math.round(dt.bal*0.10 + interest)));
    dt.bal = Math.max(0, dt.bal + interest - pay);
    expense += pay;
    if(dt.bal<=0){ tx('Cleared: '+esc(dt.name)); toast('Debt cleared: '+esc(dt.name), 3000); log('money','You cleared the '+dt.name+'. Sleep improves immediately.','good'); }
    else tx(dt.name+' −'+fmt(pay));
  });
  S.fin.debt = (S.fin.debt||[]).filter(x=>x.bal>0.5);

  // ---- debt that can never be serviced gets restructured rather than compounding forever
  (S.fin.debt||[]).forEach(function(dt){
    const service = dt.bal*dt.rate + dt.minPay;
    if(dt.kind==='shark' && service > income*0.55 && (S.turn - (dt.started||S.turn)) >= 2){
      if(dt.warned !== S.turn && R.chance(0.45)){
        dt.warned = S.turn;
        const relief = Math.round(dt.bal*0.35);
        dt.bal = Math.max(0, dt.bal - relief); dt.rate = 0.10; dt.minPay = Math.round(dt.bal*0.15); dt.kind='bank';
        dt.name = 'Restructured debt';
        log('money','The lender accepted a restructuring: '+fmt(relief)+' written off, the balance moved to 10% a quarter. They would rather be paid something.','warn');
      }
    }
  });
  // ---- the ledger closes
  S.fin.cash += income - expense;
  S.quarter = {income:income, expense:expense};

  // ---- overdraft / survival
  if(S.fin.cash < 0){
    const affordable = Math.max(0, (income*0.35) - (S.fin.debt||[]).reduce((a,x)=>a+x.minPay+x.bal*x.rate,0));
    if(S.fin.credit > 15 && affordable > 0 && R.chance(0.55)){
      const amt = Math.min(Math.round(-S.fin.cash*1.15), Math.round(affordable/0.09));
      S.fin.debt.push({id:'d'+ (++S.seq), name:'Overdraft', bal:amt, rate:0.09, minPay:Math.round(amt*0.3), kind:'bank'});
      S.fin.cash += amt;
      log('money','The bank covered a shortfall of '+fmt(amt)+'. You are now paying 14% a quarter for the privilege.','bad');
    } else if(R.chance(0.6)){
      const amt = Math.round(-S.fin.cash*1.2);
      S.fin.debt.push({id:'d'+(++S.seq), name:'Informal lender', bal:amt, rate:0.18, minPay:Math.round(amt*0.35), kind:'shark'});
      S.fin.cash += amt;
      log('money','You borrowed '+fmt(amt)+' from a private lender at 30% a quarter. There is no paperwork and no mercy.','bad');
      p.stress = clamp(p.stress+9,0,100);
    } else {
      log('money','You ended the quarter in the red. Essentials got skipped.','bad');
      p.health = clamp(p.health-3.2,0,100); p.happy = clamp(p.happy-4,0,100);
      S.fin.credit = clamp(S.fin.credit-7,0,100);
      S.fin.cash = Math.max(S.fin.cash, -budgetMonthly()*6);
    }
    S.fin.credit = clamp(S.fin.credit-3,0,100);
  } else {
    S.fin.credit = clamp(S.fin.credit+0.8,0,100);
  }
  // credit score drifts with repayment behaviour
  if(debtTotal()<=0) S.fin.credit = clamp(S.fin.credit+1.4,0,100);
}

function fireFromJob(){
  const p=S.p;
  if(!p.job) return;
  log('career','You were let go from '+p.job.title+'. Performance had been flagged for two quarters.','bad');
  p.stress = clamp(p.stress+16,0,100); p.happy = clamp(p.happy-12,0,100); p.rep = clamp(p.rep-4,0,100);
  p.job = null; p.jobPerf = 50; p.jobYears = 0;
}

/* ------------------------------------------------------------------------
   The hours budget. A quarter is thirteen weeks. Work, sleep, commuting and
   eating are spent before you get here; what is left is discretionary, and
   it is the only thing any of these actions can draw on. You can spend hours
   you do not have by not sleeping, but the debt is collected.
   ------------------------------------------------------------------------ */
const WEEKS_PER_QUARTER = 13;
function weeklyFreeHours(){
  let h = 26;
  if(S.p.job)           h -= 6;
  if(S.biz)             h -= 7;
  if(S.p.married)       h -= 3;
  if(S.p.kids > 0)      h -= 5 * Math.min(S.p.kids, 3);
  if(S.flags.moonlight) h -= 4;
  h += houseTimeBoost() * 12;
  return Math.max(4, Math.round(h));
}
function hoursBudget(){ return weeklyFreeHours() * WEEKS_PER_QUARTER; }
function hoursSpent(){ return S.p.spent || 0; }
function hoursLeft(){ return Math.max(0, hoursBudget() - hoursSpent()); }
function sleepDebt(){ return S.p.debt || 0; }
function spendHours(n, allowDebt){
  n = Math.round(n);
  const left = hoursLeft();
  if(n <= left){ S.p.spent = hoursSpent() + n; return 0; }
  if(!allowDebt) return -1;
  const borrowed = n - left;
  S.p.spent = hoursSpent() + left;
  S.p.debt  = sleepDebt() + borrowed;
  return borrowed;
}
function repeatFactor(id){
  const n = (S.p.acts || {})[id] || 0;
  return 1 / (1 + n * 0.62);
}
function noteAction(id){
  if(!S.p.acts) S.p.acts = {};
  S.p.acts[id] = (S.p.acts[id] || 0) + 1;
}

/* ---- career actions ---- */
/** @type {CAREERShape[]} */
const CAREER = [
  {id:'grind', label:'Work late, deliver hard', cost:0, hours:52, borrow:true,
   hint:'Four extra hours a week, every week, for a whole quarter. It works, and then it stops working. The second lot of late nights in one quarter buys far less than the first.',
   can:s=>!!s.p.job,
   run:()=>{
     const f = repeatFactor('grind');
     const debt = spendHours(52, true);
     const gain = R.range(6,13) * f;
     S.p.jobPerf=clamp(S.p.jobPerf+gain,0,99);
     S.p.stress=clamp(S.p.stress+R.range(5,10)*(0.6+0.6*f)+debt*0.05,0,100);
     S.p.skills.ops=clamp(S.p.skills.ops+R.range(0.6,1.6)*f,0,100);
     S.p.happy=clamp(S.p.happy-2-3*(1-f),0,100);
     noteAction('grind');
     const msg = f>0.72 ? 'You grind. Output goes up. So does the quiet resentment.'
       : f>0.45 ? 'Another run of late nights. It moves the needle less than the last lot did.'
       : 'You are working late out of habit now. Nobody is getting much out of it, least of all you.';
     log('career', msg, f>0.72?'neutral':'warn');
     return 'Performance +'+Math.round(gain)+(debt>0 ? ', borrowed '+debt+'h from sleep' : '');
   }},
  {id:'network', label:'Take people to lunch', cost:60000, hours:18,
   hint:'Relationship capital compounds faster than money capital early on. It takes afternoons, though, and the same people can only be asked to lunch so often before it becomes a story about you.',
   can:()=>hoursLeft() >= 18,
   run:()=>{
     const f = repeatFactor('network');
     spendHours(18, false);
     S.fin.cash-=60000;
     S.p.skills.network=clamp(S.p.skills.network+R.range(1.5,3.6)*f,0,100);
     S.p.rep=clamp(S.p.rep+R.range(0.8,2.4)*f,0,100);
     S.p.stress=clamp(S.p.stress-2*f,0,100);
     noteAction('network');
     const msg = f>0.72 ? 'Three lunches, two coffees, one introduction that might matter.'
       : f>0.45 ? 'More lunches. You are starting to see the same faces.'
       : 'You are lunching out of obligation now. It is not buying you anything new.';
     log('career', msg, f>0.72?'neutral':'warn');
     return 'Network and reputation up'+(f<0.72?' (diminishing)':'')+'.';
   }},
  {id:'raise', label:'Ask for a raise', cost:0,
   hint:'Odds scale with performance, tenure and how replaceable you are.',
   can:s=>!!s.p.job && (s.cd.raise == null || (s.turn - s.cd.raise) >= 4),
   odds:s=>clamp(0.10 + (s.p.jobPerf-45)/160 + s.p.jobYears*0.035 + s.p.skills.network/900, 0.05, 0.88),
   run:()=>{ const s=S.p; S.cd.raise = S.turn;
     const ok=R.chance(clamp(0.10+(s.jobPerf-45)/160+s.jobYears*0.035+s.skills.network/900,0.05,0.88));
     if(ok){
       const mkt = marketMonthly();
       const target = Math.min(Math.round(Math.max(s.job.monthly*1.10, mkt*0.95)), Math.round(mkt*1.18));
       const inc = target/s.job.monthly - 1;
       s.job.monthly = target; s.jobPerf = clamp(s.jobPerf+4,0,99);
       log('career','You asked. They said yes: '+fmt(target)+'/month'+(Math.abs(inc)>0.005?' ('+(inc>=0?'+':'')+pct(inc,0)+')':'')+'. Turns out the meeting was the hard part.','good');
       return inc>0.005 ? 'Raise secured: +'+pct(inc,0)+'.' : 'You are already at the top of what this role pays.';
     }
     s.jobPerf=clamp(s.jobPerf-6,0,99); s.rep=clamp(s.rep-1.5,0,100);
     log('career','"Let us revisit at the next review." You have been put on a list.','bad'); return 'Rejected. Performance dipped.'; }},
  {id:'jump', label:'Interview elsewhere', cost:45000,
   hint:'The fastest way to close the gap between what you are paid and what you are worth.',
   can:s=>!s.cd.jobJump || (s.turn - s.cd.jobJump) >= 6,
   odds:s=>clamp(0.16 + s.p.skills.ops/420 + s.p.skills.network/320 + s.p.rep/900, 0.06, 0.9),
   run:()=>{ const s=S.p;
     const p=clamp(0.16+s.skills.ops/420+s.skills.network/320+s.rep/900,0.06,0.9);
     S.cd.jobJump = S.turn;
     if(R.chance(p)){
       const was = s.job?s.job.monthly:0;
       const offer = Math.round(marketMonthly()*R.range(0.85,1.22));
       s.job={title:R.pick(['Senior Associate','Manager','Lead','Head of Function','Specialist']), monthly:offer, industry:'Corporate'};
       s.jobPerf=58; s.jobYears=0; s.stress=clamp(s.stress+7,0,100); s.rep=clamp(s.rep+2,0,100);
       const inc = was>0 ? (offer/was - 1) : 0;
       log('career','You moved to '+s.job.title+' at '+fmt(offer)+'/month'+(was>0?' ('+(inc>=0?'+':'')+pct(inc,0)+')':'')+'. New title, new politics, better money.','good');
       return was>0 ? 'New job: '+fmt(offer)+'/mo ('+(inc>=0?'+':'')+pct(inc,0)+')' : 'Hired at '+fmt(offer)+'/mo';
     }
     s.happy=clamp(s.happy-4,0,100); s.stress=clamp(s.stress+4,0,100);
     log('career','Four interviews, two finals, no offer. You go back to your desk.','bad'); return 'No offer this time.'; }},
  {id:'sidehustle', label:'Run a side hustle after hours', cost:0, hours:88, borrow:true,
   hint:'Seven hours a week of evenings and weekends, sold off in blocks. There are only so many nights in a quarter — take on a second hustle and the second one comes out of your sleep.',
   can:()=>true,
   run:()=>{
     const f = repeatFactor('sidehustle');
     const debt = spendHours(88, true);
     const earn=Math.round(R.range(0.75,1.35)*(60000 + S.p.skills.hustle*5200)*CITY().payMult*f);
     S.fin.cash+=earn;
     S.p.stress=clamp(S.p.stress+R.range(7,13)*(0.6+0.6*f)+debt*0.07,0,100);
     S.p.skills.hustle=clamp(S.p.skills.hustle+R.range(0.8,2.2)*f,0,100);
     S.p.health=clamp(S.p.health-1.4-debt*0.035,0,100);
     noteAction('sidehustle');
     log('career', debt>0
       ? 'You ran out of evenings and started using the night. You made '+fmt(earn)+', and you will pay for it.'
       : 'Evenings and weekends sold off in blocks. You made '+fmt(earn)+'.', debt>0?'warn':'neutral');
     return 'Earned '+fmt(earn)+(debt>0 ? ', borrowed '+debt+'h from sleep' : ', paid for it in sleep');
   }},
  {id:'quit', label:'Resign and go full-time on the business', cost:0,
   hint:'Burn the boats. Business output jumps — and so does the cost of being wrong.',
   can:s=>!!s.p.job,
   run:()=>{ log('career','You resigned. No salary, no structure, no excuse.','warn');
     S.p.job=null; S.p.jobYears=0; S.p.happy=clamp(S.p.happy+6,0,100); S.p.stress=clamp(S.p.stress+10,0,100);
     if(S.p.family<60){ S.p.family=clamp(S.p.family-8,0,100); log('life','Your family does not understand what you just did.','bad'); }
     return 'Unemployed by choice. Business output up.'; }},
  {id:'sabbatical', label:'Take a month off to reset', cost:0, hours:0,
   hint:'Sometimes the highest-return action available is stopping. Once a year, at most — a month off every quarter is not a sabbatical, it is unemployment.',
   can:s=>s.fin.cash>400000 && (!s.cd.sab || (s.turn - s.cd.sab) >= 4),
   run:()=>{ S.fin.cash-=Math.round(budgetMonthly()*1.2); S.p.stress=clamp(S.p.stress-26,0,100); S.p.health=clamp(S.p.health+7,0,100);
     S.p.happy=clamp(S.p.happy+11,0,100); S.p.jobPerf=clamp(S.p.jobPerf-5,0,99); S.p.family=clamp(S.p.family+4,0,100);
     S.cd.sab = S.turn;
     S.p.debt = Math.max(0, sleepDebt() - 90);
     log('life','You stopped. Nothing collapsed. That was the lesson.','good'); return 'Stress down sharply.'; }},
];

/* =========================================================================
   Section 6: Business engine
   ========================================================================= */
/* One number, used by every picker. It used to be three: the first-company
   card showed T.min, the second-company modal showed T.min*S.cumInfl, and a
   third card showed BIZ.startCost — a field that does not exist, so that
   card priced every business at ₦NaN. */
function startBizCost(typeId){ const T=BIZ.find(x=>x.id===typeId); return Math.round((T?T.min:0) * (S.cumInfl||1)); }
/* A SECOND ownerTime() was declared after this one and shadowed it: in the
   flat build a later function declaration of the same name simply overwrote
   the earlier one, so this was dead code no gate could see. Deleted rather
   than kept, and safe to delete - the surviving version returns the same value
   when handed no business. This is the class of bug a module boundary finds
   for free. */
function marketSalary(skill){
  const talent = (S && S.tune) ? (S.tune.talent||1) : 1;
  return Math.round((95000 + skill*58000) * CITY().payMult * S.cumInfl * talent);
}
/** @type {EDUShape} */
const EDU = {'Secondary':0.55,'HND':0.88,'BSc':1.00,'MSc':1.14,'MBA':1.22,'PhD':1.18,'Dropout':0.50};
function eduMult(){ return EDU[S.p.edu] || 1; }
/* What the market pays someone with your skills, experience and education right now.
   Job-hopping closes the gap to this number. It does not compound past it. */
function marketMonthly(){
  const k = S.p.skills, yrs = Math.min(10, S.p.jobYears||0);
  const base = 90000 + k.ops*5000 + k.tech*4200 + k.finance*3200 + k.network*2600 + yrs*11000;
  return Math.max(120000, Math.round(base * CITY().payMult * eduMult() * (0.75 + S.p.rep/220) * S.cumInfl));
}
/* The trait a staff member carries, by id, or an empty one when the id is not in
   the table. One place, and typed: TRAITS is a data table, so the fields it
   holds are known, and every rule that reads one off a member now reads them off
   the table's own element type instead of off `{}`. It is also what found the
   hiring message below, which looked up a trait by comparing it to itself and
   printed the word "undefined" to the player on every hire. */
/** @param {string} id @returns {Partial<(typeof TRAITS)[number]>} */
function traitOf(id){
  return TRAITS.find(function(x){ return x.id===id; }) || {};
}
function staffProd(b){
  b = b || S.biz; if(!b) return 0;
  let t=0;
  (b.staff||[]).forEach(s=>{
    const tr = traitOf(s.trait);
    const roleMult = (s.role==='gm') ? 1.18 : (s.role==='sales') ? 1.10 : 1.0;
    const fit = (s.outlet && (b.outlets||[]).some(o=>o.id===s.outlet)) ? 1.0 : (b.outlets&&b.outlets.length>1 ? 0.88 : 1.0);
    const ramp = (s.ramp === undefined) ? 1 : (s.ramp||0);          // fully ramped if hired before this existed
    const notice = (s.leaving !== undefined) ? 0.65 : 1;            // serving notice, mentally gone
    t += (0.55 + s.skill/10) * (s.morale/74) * (1 + (tr.output||0)) * roleMult * fit * ramp * notice;
  });
  return t;
}
function staffMonthly(b){
  b = b || S.biz; if(!b) return 0;
  const own = (b.staff||[]).reduce((a,s)=>a+s.salary,0);
  // Household staff on the company payroll are a wage cost like any other, and they
  // can push the company into the same missed-payroll trouble. That is deliberate.
  return own + houseMonthlyBiz(b.id);
}
function theftRate(b){ b = b || S.biz; if(!b) return 0; return (b.staff||[]).reduce((a,s)=>{const t=traitOf(s.trait); return a + (t.theft||0);},0)*0.010; }
function connBonus(b){ b = b || S.biz; if(!b) return 0; return (b.staff||[]).reduce((a,s)=>{const t=traitOf(s.trait); return a + (t.demand||0);},0); }

/* ------------------------- portfolio: several companies -------------------- */
function bizList(){ return (S.bizs||[]).filter(Boolean); }
/* A kind of company, as a picture: its icon, its name and price, and the four
   things that decide whether it suits you - margin, growth, labour, regulatory
   risk - as meters, with the exact figures one tap away in the fold. Both
   renderers draw the start-a-company grid from this one tile, so they cannot
   disagree about it; the buttons are the screen's own, with their refusal. */
function bizTypeTileHTML(t){
  const cost = startBizCost(t.id), afford = S.fin.cash >= cost;
  const meter = function(ico, label, v, tone){
    return '<div class="bmeter" title="'+label+'"><span class="gfx bmi" aria-hidden="true">'+ico+'</span>'+
      '<span class="gfx bmb" role="img" aria-label="'+label+'"><i style="width:'+Math.round(Math.max(4, Math.min(100, v * 100)))+'%;background:'+tone+'"></i></span></div>';
  };
  return '<div class="btile'+(afford ? '' : ' off')+'">'+
    '<div class="gfx bico" aria-hidden="true">'+worldGlyph(t.id)+'</div>'+
    '<div class="bname"><b>'+t.name+'</b><span class="mono">'+fmt(cost)+'</span></div>'+
    '<div class="bmeters">'+
      meter(worldIco('coins'), 'margin '+pct(t.margin, 0), t.margin, t.margin > 0.5 ? 'var(--good)' : 'var(--info)')+
      meter(worldIco('trend'), 'growth '+pct(t.growth, 0)+' a quarter', t.growth / 0.3, 'var(--info)')+
      meter(worldIco('people'), 'labour '+t.laborPer, t.laborPer / 6, t.laborPer > 4 ? 'var(--warn)' : 'var(--info)')+
      meter(worldIco('warn'), 'regulatory risk '+pct(t.regRisk, 0), t.regRisk * 2, t.regRisk > 0.3 ? 'var(--bad)' : 'var(--info)')+
    '</div>'+
    foldHTML('What it is', t.desc+' Margin '+pct(t.margin, 0)+' · growth '+pct(t.growth, 0)+'/q · labour '+
      t.laborPer+' · regulatory risk '+pct(t.regRisk, 0)+'.')+
    (afford ? '' : '<div class="row wrap" style="gap:5px"><span class="chip y">short '+fmt(cost - S.fin.cash)+'</span></div>')+
    '<div class="row" style="gap:6px">'+
      '<button class="btn sm '+(afford ? 'primary' : '')+'" style="flex:1" data-a="startbiz" data-t="'+t.id+'"'+
        (afford ? '' : ' disabled aria-disabled="true" title="Needs '+fmt(cost)+' · you have '+
          fmt(S.fin.cash)+' · short '+fmt(cost - S.fin.cash)+' · or take a partner"')+'>'+
        (afford ? 'Start' : 'Start alone')+'</button>'+
      /* a partner is how you afford what you cannot afford alone, so this one
         is NOT disabled with it */
      '<button class="btn sm '+(afford ? '' : 'primary')+'" data-a="startbizpartner" data-t="'+t.id+'"'+
        (S.fin.cash > 0 ? '' : ' disabled aria-disabled="true"')+
        ' title="Covers the '+fmt(Math.max(0, cost - S.fin.cash))+' you cannot, for a permanent share of it"'+
        '>With partner</button>'+
    '</div></div>';
}
function bizById(id){ return bizList().find(function(b){ return b.id===id; }) || null; }
function setActiveBiz(id){
  const b = bizById(id); if(!b) return false;
  S.biz = b; S.activeBiz = b.id; return true;
}
function ownerTime(b){
  const avail = S.p.job ? (S.flags.moonlight ? 0.62 : 0.32) : 1.0;
  const list = bizList();
  if(!b || list.length <= 1) return avail;
  // a business with a general manager needs far less of you personally
  const w = list.map(function(x){ return (x.staff||[]).some(function(st){ return st.role==='gm'; }) ? 0.34 : 1; });
  const tot = w.reduce(function(a,x){ return a+x; }, 0) || 1;
  const idx = Math.max(0, list.indexOf(b));
  const span = 1 + S.p.skills.ops/230;      // you get better at covering ground
  return clamp(avail * ((w[idx]||1)/tot) * span, 0.04, 1.0);
}
function outletValue(o){
  if(!o || o.status==='building') return 0;
  const site = (o.site===undefined?70:o.site);
  const mgr  = (o.manager? 1.06 : 1.0);
  return (o.size||1) * (0.55 + (o.cond===undefined?80:o.cond)/200) * (0.62 + site/140) * mgr;
}
function outletScale(b){
  if(!b) return 0;
  const os = (b.outlets && b.outlets.length) ? b.outlets : null;
  if(!os || !os.length) return Math.max(0.2, b.locations||1);
  // outlets in the same city eat each other's catchment; across cities they do not
  const byCity = {};
  os.forEach(function(o){
    const c = o.city || S.city;
    byCity[c] = (byCity[c]||0) + outletValue(o);
  });
  let tot = 0;
  Object.keys(byCity).forEach(function(c){ if(byCity[c]>0) tot += Math.pow(byCity[c], 0.92); });
  return tot;
}
function outletOpen(b){ return ((b&&b.outlets)||[]).filter(function(o){ return o.status!=='building'; }); }
function staffNeed(b){
  const os = outletOpen(b);
  if(!os.length) return 1;
  return Math.max(1, Math.round(os.reduce(function(a,o){ return a + (o.size||1)*1.25; }, 0)));
}
function staffCover(b){
  const need = staffNeed(b);
  return clamp((b.staff||[]).length / Math.max(1,need), 0, 1.4);
}
/* distribute the company P&L across units so you can see which ones work */
function allocateOutlets(b, revenue, cogs, opex, profit){
  const os = outletOpen(b); if(!os.length) return;
  const vals = os.map(function(o){ return Math.max(0.05, outletValue(o)); });
  const tot = vals.reduce(function(a,x){ return a+x; }, 0) || 1;
  os.forEach(function(o,i){
    const sh = vals[i]/tot;
    o.revenue = Math.round(revenue*sh);
    o.cost    = Math.round((cogs+opex)*sh);
    o.profit  = Math.round(profit*sh);
    o.share   = sh;
  });
}
function companyCulture(b){
  const st = (b&&b.staff)||[]; if(!st.length) return 50;
  let c = 50;
  const fair = st.reduce(function(a,x){ return a + (x.salary/Math.max(1,marketSalary(x.skill))); }, 0)/st.length;
  c += (fair-1)*45;
  c += ((b.staffTrust||55)-55)*0.35;
  c -= (b.arrears>0? 22:0);
  c += st.reduce(function(a,x){ return a + ((x.trained||0)*3); },0)/st.length;
  c -= st.reduce(function(a,x){ return a + (x.morale<35?6:0); },0);
  return clamp(c, 0, 100);
}
function outletRent(b){
  const os = (b && b.outlets && b.outlets.length) ? b.outlets : null;
  if(!os) return (BIZ.find(function(x){return x.id===b.type;})||{rentQ:400000}).rentQ*0.6*(b.locations||1);
  return os.reduce(function(a,o){
    const r = (o.rent||0)*(o.size||1);
    return a + (o.status==='building' ? r*0.5 : r);
  }, 0);
}
function outletCount(b){ return (b && b.outlets && b.outlets.length) ? outletOpen(b).length : (b? (b.locations||1) : 0); }
function outletAvgCond(b){
  const os = (b && b.outlets) ? b.outlets : [];
  if(!os.length) return 80;
  return os.reduce(function(a,o){ return a + (o.cond===undefined?80:o.cond); },0)/os.length;
}
function outletCities(b){
  const os=(b&&b.outlets)||[]; const set={}; os.forEach(function(o){ set[o.city||S.city]=1; });
  return Object.keys(set).length;
}
function openOutlet(b, opts){
  if(!b) return null;
  opts = opts||{};
  const T = BIZ.find(function(x){return x.id===b.type;});
  const city = opts.city || S.city;
  const cm = CITIES.find(function(c){ return c.id===city; }) || CITY();
  const grade = opts.site===undefined ? R.int(42, 94) : opts.site;
  const gradeMult = 0.62 + grade/115;                       // a good position costs real money
  const rent = Math.round(T.rentQ*0.6*cm.rentMult*R.range(0.85,1.25)*gradeMult);
  const fit  = Math.round(Math.max(2500000, (b.revenue||0)*0.45 + T.rentQ*3)*S.cumInfl*cm.rentMult*gradeMult);
  /* trading:true is used when a commitment has already carried the build -
     the delay was paid for before the unit existed, not after. */
  const trading = !!opts.trading;
  const build = trading ? 0 : 1 + (R.chance(0.35)?1:0) + (city!==S.city?1:0);   // further away takes longer
  const o = {id:'o'+(++S.seq), name:opts.name || (T.name.replace(/ .*/,'')+' '+(b.outlets.length+1)),
    size:1, cond:82, rent:rent, end:S.turn+R.int(6,12), landlord:R.pick(LAST), goodwill:50, hikes:0,
    city:city, staff:[], maint:0, opened:S.turn, fitout:fit,
    site:grade, status:trading?'open':'building', opensAt:S.turn+build, buildCost:fit, manager:null, revenue:0, cost:0, profit:0};
  b.outlets = b.outlets || [];
  b.outlets.push(o);
  b.locations = b.outlets.length;
  if(!trading){                                            // a commitment already paid for this
    b.cash -= Math.round(fit*0.45);                        // deposit and first draw
    b.capex += Math.round(fit*0.25);
  }
  if(!b.lease) b.lease = o;
  log('biz','You signed for a unit in '+cm.label+' ('+(grade>80?'an excellent':grade>62?'a decent':'a mediocre')+
    ' position). Fit-out is underway and it should be trading in about '+build+' quarter'+(build===1?'':'s')+'.','neutral');
  return o;
}
function closeOutlet(b, oid){
  if(!b || !b.outlets) return null;
  const o = b.outlets.find(function(x){ return x.id===oid; }); if(!o) return null;
  if(b.outlets.length<=1) return null;
  // staff at that outlet: redeploy or pay off
  let sev = 0;
  (b.staff||[]).slice().forEach(function(st){
    if(st.outlet===oid){
      if(R.f()<0.55){ st.outlet = null; }   /* seeded: a season run must be reproducible */
      else { sev += Math.round(st.salary*(S.turn-(st.joined||S.turn)>8?2:1)); b.staff = b.staff.filter(function(x){return x.id!==st.id;}); }
    }
  });
  b.outlets = b.outlets.filter(function(x){ return x.id!==oid; });
  b.locations = b.outlets.length;
  b.cash -= sev + Math.round((o.fitout||0)*0.12);
  b.capex = Math.max(0, Math.round(b.capex*0.9));
  b.lease = b.outlets[0] || null;
  log('biz','You closed the '+esc(o.name)+' unit. Severance and dilapidations: '+fmt(sev)+'.','warn');
  return o;
}
function upgradeOutlet(b, oid){
  const o = (b && b.outlets) ? b.outlets.find(function(x){ return x.id===oid; }) : null; if(!o) return null;
  if((o.size||1) >= 4) return null;
  const cost = Math.round((o.fitout||3000000)*0.55*(o.size||1)*S.cumInfl);
  if(b.cash < cost) return null;
  b.cash -= cost; b.capex += Math.round(cost*0.7);
  o.size = (o.size||1)+1; o.cond = clamp((o.cond||80)+12,0,100);
  o.rent = Math.round((o.rent||0)*1.35);
  log('biz','You extended the '+esc(o.name)+' unit for '+fmt(cost)+'. Capacity up, rent up.','good');
  return o;
}
function maintainOutlet(b, oid, amt){
  const o = (b && b.outlets) ? b.outlets.find(function(x){ return x.id===oid; }) : null; if(!o) return null;
  const spend = Math.min(amt, Math.max(0,b.cash));
  if(spend<=0) return null;
  b.cash -= spend;
  o.cond = clamp((o.cond||80) + spend/Math.max(1,(o.fitout||3000000)*0.012), 0, 100);
  o.maint = (o.maint||0) + spend;
  return o;
}
function stepOutlets(b){
  const notes = [];
  (b.outlets||[]).forEach(function(o){
    // under construction: it costs money and earns nothing
    if(o.status==='building'){
      const draw = Math.round((o.buildCost||0)*0.28);
      b.cash -= draw; b.capex += Math.round(draw*0.8);
      if(S.turn >= (o.opensAt||S.turn)){
        const overrun = Math.round((o.buildCost||0)*R.range(0, 0.42));
        if(overrun>0){ b.cash -= overrun; b.capex += Math.round(overrun*0.7); }
        o.status = 'open';
        o.cond = clamp((o.cond||82) - 4, 0, 100);
        notes.push({level: overrun>0?'warn':'good', text: o.name+' is open and trading.'+(overrun>0?
          ' The fit-out overran by '+fmt(overrun)+', which is what fit-outs do.':' It came in on budget, which is rare.')});
      }
      return;
    }
    // a unit manager holds the place together
    if(o.manager && !(b.staff||[]).some(function(x){ return x.id===o.manager; })) o.manager = null;
    // condition decays with trade and age; maintenance holds it up
    const wear = 1.6 + (o.size||1)*0.7 + (S.mkt.infl*8);
    o.cond = clamp((o.cond===undefined?80:o.cond) - wear*R.range(0.6,1.4) + ((o.maint||0)>0?0.9:0) + (o.manager?0.8:0), 0, 100);
    o.maint = 0;
    o.end = (o.end||S.turn+8) - 1;
    if(o.end <= 0){
      const hike = clamp(R.gauss(S.mkt.infl*0.85, 0.055) - ((o.goodwill===undefined?50:o.goodwill)-50)/900, -0.04, 0.34);
      const gw = o.goodwill===undefined?50:o.goodwill;
      if(R.chance(clamp(gw/130 + 0.3, 0.2, 0.94))){
        o.rent = Math.round((o.rent||0)*(1+hike)); o.end = R.int(6,12); o.hikes=(o.hikes||0)+1;
        notes.push({level: hike>0.2?'bad':'warn', text:'Lease renewed at '+esc(o.name)+': '+fmt(o.rent)+'/mo, up '+Math.round(hike*100)+'%.', outlet:o.id});
      } else {
        notes.push({level:'bad', text:'The landlord at '+esc(o.name)+' will not renew. You have one quarter to find premises.', outlet:o.id});
        o.end = 1;
      }
    }
  });
  return notes;
}

function startBiz(typeId, name, capital, partner){
  const T = BIZ.find(x=>x.id===typeId);
  const infl = S.cumInfl;
  const c = Math.min(capital, S.fin.cash);
  S.fin.cash -= c;
  const eq = partner ? (100 - partner.equity) : 100;
  const nb = {
    id:'b'+(++S.seq),
    type:typeId, name:name||T.name, foundedTurn:S.turn, startInfl:infl,
    equity:eq, partner:partner||null, cash:Math.round(c*0.75), capex:Math.round(c*0.25),
    staff:[], priceIdx:1.0, marketing:0, quality:55, rep:45, locations:1, brand:0,
    qualitySpendMonthly:0, formal:false, revenue:0, cogs:0, opex:0, profit:0, tax:0,
    units:0, capacity:0, demand:0, history:[], morale:65, conn:0, moonlight:false,
    lastNotes:[],
    /* --- depth --- */
    recv:0, payable:0, inventory:0, creditTerms:0.15, stockPolicy:0.58, draw:0,
    positioning:45, discountMemory:0, lastPriceIdx:1.0, priceOver:0, priceUnder:0,
    qualInvest:55, defects:[], pendingDefects:0, defectBill:0, defectsQ:0, warrantyQ:0,
    custBase:0, churnQ:0, cacQ:0, boughtQ:0, referredQ:0, womQ:0, rivalCut:0,
    compliance:42, taxRisk:0, auditPending:0, auto:0, products:1, arrears:0,
    lease:{rent:Math.round(T.rentQ*0.25), end:S.turn+8, landlord:R.pick(LAST), goodwill:50, hikes:0},
    keyClient:null, supplierConf:70, supplierDays:30, staffTrust:55, insured:false,
    incidents:[], contracts:[], diag:[], lastRevenue:0, quarters:0, everProfitable:0,
    outlets:[], bids:[], openRoles:[]
  };
  nb.outlets.push({id:'o'+(++S.seq), name:(name||T.name)+' \u2014 unit 1', size:1, cond:85,
    rent:Math.round(T.rentQ*0.6*CITY().rentMult), end:S.turn+8, landlord:R.pick(LAST), goodwill:52, hikes:0,
    city:S.city, staff:[], maint:0, opened:S.turn, fitout:Math.round(c*0.25),
    site:R.int(58,88), status:'open', opensAt:S.turn, manager:null, revenue:0, cost:0, profit:0});
  nb.lease = nb.outlets[0];
  nb.locations = 1;
  ensureGov(nb);
  if(partner){
    nb.cash += partner.capital; nb.capex += Math.round(partner.capital*0.2);
    S.p.skills.network = clamp(S.p.skills.network + 4, 0, 100);
    const wantsBoard = (partner.ask||'').toLowerCase().indexOf('board') >= 0;
    const holder = addHolder(nb, {name:partner.name, kind:'partner', board:wantsBoard,
      trust:(partner.trust||60), seniority:1, kindName:'Founding partner'});
    holder.skillKey = partner.skill; holder.bg = partner.bg; holder.ask = partner.ask;
    grantPct(nb, partner.equity, {holderId:holder.id, capital:partner.capital, noCash:true});
    if(wantsBoard || partner.equity >= 25) formBoard(nb);
  }
  ensureGov(nb);
  if(!S.bizs) S.bizs = [];
  S.bizs.push(nb);
  S.biz = nb; S.activeBiz = nb.id;
  log('biz','You started '+nb.name+' with '+fmt(c)+' of your own money.'+(partner?' '+partner.name+' took '+partner.equity+'% for '+fmt(partner.capital)+'.':''), 'good');
  log('biz', T.desc, 'neutral');
  S.p.stress = clamp(S.p.stress+8, 0, 100);
  recompute();
  return nb;
}
function startAnotherBiz(typeId, name, capital, partner){ return startBiz(typeId, name, capital, partner); }
function dropBiz(b){
  if(!b) return;
  if(!S.bizs) S.bizs = [];
  S.bizs = S.bizs.filter(function(x){ return x && x.id!==b.id; });
  if(S.biz && S.biz.id===b.id) S.biz = S.bizs.length ? S.bizs[0] : null;
  S.activeBiz = S.biz ? S.biz.id : null;
}
function closeBiz(reason, bb){
  const b = bb || S.biz; if(!b) return;
  const salvage = Math.max(0, Math.round(b.cash*0.6 + b.capex*0.25));
  S.fin.cash += salvage;
  log('biz', b.name+' is wound up. '+reason+' You salvage '+fmt(salvage)+'.', 'bad');
  S.p.stress = clamp(S.p.stress+12,0,100); S.p.happy = clamp(S.p.happy-8,0,100);
  S.p.skills.ops = clamp(S.p.skills.ops+3,0,100);
  S.flags.hadBiz = true; S.flags.bizFailures = (S.flags.bizFailures||0)+1;
  dropBiz(b);
}
/* ===========================================================================
   Commitments

   A business is not a set of dials. It is a set of promises already made:
   leases signed, offers accepted, fit-outs paid for. Those promises arrive
   late, they cost money the whole time they are arriving, and they cannot be
   unmade for free. Those three properties - delay, bleed, irreversibility -
   are what make a decision hard, and the game had none of them. expandBiz()
   added a location the same quarter you paid for it. hire() delivered a
   fully productive human being the day you signed them. Both were dials.

   No closures are stored in here: state is serialised, so a commitment keeps
   plain data and commitActivate() switches on its kind.
   =========================================================================== */
function commitNew(b, spec){
  b.commitments = b.commitments || [];
  const c = Object.assign({ id:'cm'+(++S.seq), kind:'generic', status:'building',
    placed:S.turn, lead:1, total:0, paid:0, breakPct:0.35, note:'' }, spec || {});
  c.readyAt = (c.readyAt===undefined) ? S.turn + (c.lead||1) : c.readyAt;
  /* the deposit is already gone; the rest is drawn evenly over the lead time */
  c.perQ = Math.round(Math.max(0, (c.total||0) - (c.paid||0)) / Math.max(1, c.lead));
  b.commitments.push(c);
  return c;
}
function commitSunk(c){ return Math.round(c.paid||0); }
/* Walking away costs everything already spent plus a share of what is left:
   the supplier keeps the deposit, the landlord keeps the rent, and the person
   you withdrew the offer on tells other people. The whole trap of the thing
   is that this number is painful enough to make finishing feel rational. */
function commitBreak(c){
  if(!c || c.status !== 'building') return 0;
  const left = Math.max(0, (c.total||0) - (c.paid||0));
  return Math.round((c.paid||0) + left * (c.breakPct===undefined ? 0.35 : c.breakPct));
}
function commitCancel(b, id){
  const c = (b.commitments||[]).find(function(x){ return x.id===id; });
  if(!c || c.status !== 'building') return 0;
  const cost = commitBreak(c);
  c.status = 'cancelled'; c.cancelledAt = S.turn; c.breakPaid = cost;
  return cost;
}
function commitBuilding(b){
  return (b.commitments||[]).filter(function(c){ return c.status === 'building'; });
}
/* What you must pay next quarter before you sell a single thing. Rent you
   cannot exit, salaries you are stuck with, fit-outs still drawing. This is
   the number that turns a downturn into a crisis, and it is the reason
   operating leverage is a strategy rather than a footnote. */
function committedFixedQ(b){
  if(!b) return { rent:0, salaries:0, builds:0, total:0 };
  const inflF = S.cumInfl / (b.startInfl || 1);
  let rent = 0;
  (b.outlets||[]).forEach(function(o){
    if(o.status === 'building') return;
    if(((o.end||0) - S.turn) > 0) rent += Math.round((o.rent||0) * inflF);
  });
  const salaries = Math.round((staffMonthly(b)||0) * 3);
  const builds = commitBuilding(b).reduce(function(a,c){ return a + (c.perQ||0); }, 0);
  return { rent: rent, salaries: salaries, builds: builds,
           total: Math.round(rent + salaries + builds) };
}
function commitActivate(b, c){
  if(c.kind === 'unit'){
    const o = openOutlet(b, { city: c.city || S.city, trading: true });
    if(o) log('biz', c.label + ' is trading. ' + fmt(Math.round(c.total)) +
      ' committed ' + (S.turn - c.placed) + ' quarters ago, opens today.', 'good');
  } else if(c.kind === 'shifts'){
    log('biz', 'The second shift starts tonight. Capacity is up a third; so is the wage bill, and nobody thanks you for it.', 'neutral');
  } else if(c.kind === 'supply'){
    c.lockedIdx = inputIndex();
    log('biz', 'The supply contract is signed. Your input cost is fixed for ' + (c.term||8) +
      ' quarters, whether that turns out to have been clever or not.', 'neutral');
  } else if(c.kind === 'channel'){
    log('biz', 'The distributor is selling for you now. Demand jumps this quarter — and 6% of revenue leaves with them, every quarter until the term is up.', 'neutral');
  } else if(c.kind === 'hire'){
    c.staff = c.staff || {};
    c.staff.ramp = 0.30;
    c.staff.joined = S.turn;
    b.staff = b.staff || [];
    b.staff.push(c.staff);
    log('biz', c.staff.name + ' has started. They will not be fully useful for a few quarters.', 'neutral');
  }
}
/* ===========================================================================
   Phase 12 — the levers that are not dials.

   Price, marketing and quality are dials: continuous, reversible, and
   effective next quarter. There is nothing hard about turning one. What a
   manager actually cannot do is reverse a decision cheaply or see its
   consequence quickly — and apart from property and hiring, the business had
   no lever with that shape at all. That is what made running it feel like
   child's play: every decision was undoable at no cost before it had even
   finished arriving.

   These three are commitments built on the phase-7 machinery, so they inherit
   its three properties — a lead time before anything arrives, money leaving
   the whole time it does, and a price for changing your mind that is meant to
   hurt. Each also has a TERM: you are in it for a number of quarters, not
   until you feel like stopping.

   Each one is worth taking because it trades a certain cost now for a bigger
   number later. Each one is dangerous for the same reason the term exists:
   the world does not wait for your commitment to end.
   =========================================================================== */
/** @type {LEVER_KINDSShape2} */
const LEVER_KINDS = {
  shifts: {
    label:'Second shift', lead:2, term:8, breakPct:0.55,
    cost:function(b){ return Math.round(2200000 * (S.cumInfl||1) * Math.max(1, outletCount(b))); },
    ask:'Run the units a second time',
    gives:'Capacity +35% for as long as it runs.',
    takes:'Wages +45%, and morale falls every quarter it runs.',
    risk:'Two quarters of lead time. The volume only pays for itself if the demand is still there when the shift arrives — and if it is not, you are paying a 45% premium to stand around.'
  },
  supply: {
    label:'Input supply contract', lead:1, term:8, breakPct:0.5,
    cost:function(b){ return Math.round(Math.max(900000, ((b.cogs||0) || (b.revenue||3000000)*0.6) * 0.12)); },
    ask:'Lock your input costs',
    gives:'Cost of goods about 10% lower for the term.',
    takes:'A deposit up front, and a fixed price whether or not it should be.',
    risk:'You are fixing a price against a world that moves. If costs fall while you are locked in, you go on paying the old one — and the card will tell you, in numbers, exactly how much that is costing you.'
  },
  channel: {
    label:'Distribution deal', lead:1, term:6, breakPct:0.5,
    cost:function(b){ return Math.round(Math.max(1200000, (b.revenue||3000000) * 0.08)); },
    ask:'Hand the selling to a distributor',
    gives:'Demand +22% for the term.',
    takes:'They take 6% of revenue off the top, every quarter of the term.',
    risk:'You stop meeting your own customers. When the term ends the demand goes with it, and you will be selling to a market that forgot you.'
  }
};
/* What a unit of input costs today. Inflation is not the only thing in it:
   when demand is weak, suppliers cut prices to keep the volume moving, which
   is precisely when a locked price stops being a bargain. */
function inputIndex(){
  const m = S.mkt || {};
  return (S.cumInfl||1) * (1 + (((m.demand||1) - 1) * 0.35));
}
function leverOf(b, kind, status){
  return (b.commitments||[]).find(function(c){
    return c.kind === kind && c.status === status && (status !== 'active' || S.turn < (c.endsAt||0));
  });
}
function leverActive(b, kind){ return !!leverOf(b, kind, 'active'); }
function leverPending(b, kind){ return !!leverOf(b, kind, 'building'); }
/* The multipliers each lever puts into the sums. Named functions, so the
   screen and the simulation read the same number and cannot drift apart. */
function shiftCapMult(b){   return leverActive(b,'shifts')  ? 1.35 : 1; }
function shiftWageMult(b){  return leverActive(b,'shifts')  ? 1.45 : 1; }
function channelDemandMult(b){ return leverActive(b,'channel') ? 1.22 : 1; }
function channelCut(b, rev){ return leverActive(b,'channel') ? Math.round((rev||0) * 0.06) : 0; }
/* Locked input cost, marked against the world. 0.90 is the discount you were
   sold; what you actually pay depends on what has happened since. */
function supplyCogsMult(b){
  const c = leverOf(b, 'supply', 'active'); if(!c) return 1;
  const spot = inputIndex(), locked = c.lockedIdx || spot;
  return clamp(0.90 * (locked / Math.max(0.01, spot)), 0.80, 1.15);
}
function supplyOverpay(b){
  const c = leverOf(b, 'supply', 'active'); if(!c) return 0;
  return Math.round((supplyCogsMult(b) / 0.90 - 1) * 100);
}
/* Walking away from one that is already running. You pay a share of the
   quarters you are giving up, plus the notice. */
function commitDropCost(c){
  if(!c || c.status !== 'active') return 0;
  const term = Math.max(1, c.term || 1);
  const left = Math.max(0, (c.endsAt || S.turn) - S.turn);
  return Math.round((c.total||0) * (c.breakPct===undefined?0.5:c.breakPct) * ((left + 1) / term));
}
function commitDrop(b, id){
  const c = (b.commitments||[]).find(function(x){ return x.id===id; });
  if(!c || c.status !== 'active') return 0;
  const cost = commitDropCost(c);
  c.status = 'ended'; c.endedAt = S.turn; c.brokeEarly = true; c.breakPaid = cost;
  return cost;
}
function leverTake(kind){
  const b = S.biz; if(!b) return;
  const K = LEVER_KINDS[kind]; if(!K) return;
  if(leverPending(b,kind)){ toast('One is already being set up'); return; }
  if(leverActive(b,kind)){ toast('That is already running'); return; }
  const cost = K.cost(b);
  confirmBox(K.ask,
    '<b>'+fmt(cost)+'</b> drawn over '+K.lead+' quarter'+(K.lead===1?'':'s')+
    ', then locked in for <b>'+K.term+' quarters</b>.<br><br>'+
    '<b>You get:</b> '+K.gives+'<br><b>You pay:</b> '+K.takes+
    '<br><br><span class="muted">'+K.risk+'</span>',
    function(){ leverPlace(kind, cost); }, 'Commit '+fmt(cost));
}
function leverPlace(kind, cost){
  const b = S.biz, K = LEVER_KINDS[kind];
  if(!b || !K) return;
  commitNew(b, { kind:kind, label:K.label, lead:K.lead, term:K.term,
                 total:cost, breakPct:K.breakPct, note:K.gives });
  log('biz', K.label + ' committed. ' + fmt(cost) + ' over ' + K.lead +
    ' quarter' + (K.lead===1?'':'s') + ' before it does anything at all.', 'neutral');
  toast(K.label + ' committed');
  render();
}

/* Nobody is productive on day one, and the people you have given notice to
   are not really there any more. Both facts used to be invisible. */
function stepRamp(b){
  (b.staff||[]).forEach(function(st){
    if(st.ramp === undefined){ st.ramp = 1; return; }      // staff hired before this existed
    st.ramp = Math.min(1, (st.ramp||0) + 0.20 + (st.skill/10) * 0.07);
  });
}
function stepCommitments(b){
  /* promises coming due */
  (b.commitments||[]).forEach(function(c){
    if(c.status !== 'building') return;
    const left = Math.max(0, (c.total||0) - (c.paid||0));
    const draw = Math.min(c.perQ||0, left);
    if(draw > 0){ c.paid = Math.round((c.paid||0) + draw); b.cash -= draw;
                  b.capex = Math.round((b.capex||0) + draw*0.8); }
    if(S.turn >= c.readyAt && c.status === 'building'){
      c.status = 'active';
      if(c.term) c.endsAt = S.turn + (c.term||0);
      commitActivate(b, c);
    }
    /* a term ends whether you are ready or not. This is the whole point of
       having one: the lever stops being yours to hold. */
    if(c.status === 'active' && c.endsAt && S.turn >= c.endsAt){
      c.status = 'ended'; c.endedAt = S.turn;
      log('biz', (c.label||'A commitment') + ' has run its term and stopped. ' +
        'Nothing was renewed, because you did not renew it.', 'neutral');
    }
  });
  /* people working out their notice leave at the end of the quarter */
  const gone = (b.staff||[]).filter(function(st){ return st.leaving !== undefined && st.leaving <= S.turn; });
  if(gone.length){
    b.staff = b.staff.filter(function(st){ return !(st.leaving !== undefined && st.leaving <= S.turn); });
    gone.forEach(function(st){ log('biz', st.name + ' worked their notice and left.', 'neutral'); });
  }
  stepRamp(b);
  /* keep the finished ones around briefly so the screen can say what happened */
  b.commitments = (b.commitments||[]).filter(function(c){
    if(c.status === 'building' || c.status === 'active') return true;
    return (S.turn - (c.endedAt || c.readyAt || S.turn)) < 2;
  });
}
/* The promises, on screen. A commitment you cannot see is not a constraint,
   it is a surprise - and the point of modelling irreversibility is that the
   player can see it coming and choose badly anyway. */
function recentGrowth(b){
  const h = (b.history||[]);
  if(h.length < 2) return 0;
  const prev = h[h.length-2].revenue || 0;
  if(prev <= 0) return 0;
  return clamp(((b.revenue||0) - prev) / prev, -1, 3);
}
function bizCapacity(b){
  const T = BIZ.find(x=>x.id===b.type);
  const capFactor = (1 + Math.log(1 + Math.max(0,b.capex)/2.5e6)*0.30) * (1 + (b.auto||0)/110);
  const loc = Math.pow(Math.max(0.2, outletScale(b)), 0.85);
  const prod = staffProd(b) + ownerTime(b)*(0.75 + S.p.skills.ops/85);
  const govOps = 1 + (boardSkill(b,'ops')-50)/850;
  return Math.max(0, prod * (230/T.laborPer) * loc * capFactor * govOps * shiftCapMult(b));
}
/* ===========================================================================
   Price is a claim, not a number

   You cannot decide to charge 18% above list. You can only charge what your
   positioning supports, and positioning is a slow stock built out of quality
   evidence, service, brand and price discipline. Charge above it and customers
   do not gently buy less - they leave, and they take the positioning with
   them. Cut repeatedly and the market learns to wait for the sale, so the
   climb back costs more than the slide ever gained.

   `priceIdx` used to be a raw elasticity multiplier: any value, effective
   instantly, fully reversible, with no memory on either side.
   =========================================================================== */
function priceBand(b){
  const pos = (b.positioning === undefined ? 45 : b.positioning);
  return { lo: 0.72 + (pos-50)/100 * 0.20,        // below this you are leaving money behind
           hi: 1.00 + (pos-50)/100 * 0.55 };      // above this customers stop believing you
}
function stepPriceMemory(b){
  const prev = (b.lastPriceIdx === undefined ? (b.priceIdx||1) : b.lastPriceIdx);
  const cur  = (b.priceIdx||1);
  const band = priceBand(b);
  /* captured before lastPriceIdx moves, or demand can never tell a rise from
     a fall and the whole memory mechanism is dead code */
  const raising = cur > prev + 0.005;
  b.priceRaising = raising;
  b.priceRise = Math.max(0, cur - prev);      // how much you are asking them to forget
  b.priceCut  = Math.max(0, prev - cur);
  /* Rule: cutting teaches the market fast, staying on sale teaches it slowly,
     and only selling at list lets it forget. An earlier version keyed this off
     the band, which was self-defeating - discounting erodes positioning, which
     lowers the band, which stopped counting as discounting, so the memory
     decayed while the business was still on sale. */
  const cutNow   = cur < prev - 0.005;
  const belowList = cur < 0.98;
  if(cutNow)        b.discountMemory = clamp((b.discountMemory||0) + 0.24, 0, 1);
  else if(belowList) b.discountMemory = clamp((b.discountMemory||0) + 0.08, 0, 1);
  else              b.discountMemory = clamp((b.discountMemory||0)*0.85 - (raising ? 0.05 : 0), 0, 1);
  b.lastPriceIdx = cur;
  b.priceOver  = Math.max(0, cur - band.hi);
  b.priceUnder = Math.max(0, band.lo - cur);
  /* positioning is earned slowly, by what you actually deliver, and a habit
     of discounting spends it */
  const earned = clamp((b.quality||50)*0.42 + (b.rep||45)*0.26
    + (b.serviceQ===undefined ? 0.85 : b.serviceQ)*28
    + Math.min(26, (b.brand||0)/Math.max(1, 4e6))
    - (b.discountMemory||0)*24, 0, 100);
  b.positioning = (b.positioning === undefined ? 45 : b.positioning)*0.82 + earned*0.18;
}
/* ===========================================================================
   Quality is a process, not a purchase

   The slider used to charge you for quality every quarter and then do nothing
   with the money: `qualitySpendMonthly` went into opex, and the only thing
   that ever moved `b.quality` was a random event. It was a money incinerator
   with a label on it.

   Real quality has two properties that make it a trap rather than a dial:

     1. LAG. Spend builds a process over quarters, and a bigger business has
        to spend more just to hold the line.
     2. DISCOVERY DELAY. The defects you ship this quarter surface three to
        six quarters later, as warranty claims and a reputation hit - long
        after the saving has been booked and spent.

   Together those produce the harvest trap: cutting quality reads as pure
   profit for two or three quarters, and the bill arrives when you have
   forgotten what you bought with it.
   =========================================================================== */
function stepQuality(b, units){
  const T = BIZ.find(x=>x.id===b.type);
  if(b.qualInvest === undefined) b.qualInvest = (b.quality===undefined ? 55 : b.quality);
  /* events move b.quality directly; fold that movement into the investment
     stock so there is exactly one writer and the two cannot disagree */
  const prevQ = (b._qualLast === undefined ? (b.quality===undefined?55:b.quality) : b._qualLast);
  if(Math.abs((b.quality||0) - (prevQ||0)) > 0.4)
    b.qualInvest = clamp(b.qualInvest + ((b.quality||0) - (prevQ||0)), 0, 100);

  const spend = b.qualitySpendMonthly||0;
  const scale = Math.max(1, (b.revenue||0) * 0.055);   // holding the line gets more expensive as you grow
  const feed  = clamp(spend/scale, 0, 2.0);
  /* The floor matters. At 14 a business that never spent on quality settled
     near 19, which made growth impossible whatever else it did - the harvest
     trap with no way out and no explanation. At 38 it settles near 48:
     mediocre, visibly mediocre, but survivable, and spending is still the
     only way to get above it. */
  const target = clamp(38 + feed*40 + (b.auto||0)*0.10 + ((b.outlets||[]).length? outletAvgCond(b)*0.12 : 0), 0, 100);
  b.qualInvest = b.qualInvest*0.80 + target*0.20;      // about five quarters to get there
  b.quality = clamp(b.qualInvest, 0, 100);
  b._qualLast = b.quality;

  /* --- the defects pipeline: built now, discovered later ----------------- */
  const defectRate = clamp((74 - b.quality)/240, 0, 0.34);
  const shipped = Math.max(0, (units||0) * defectRate);
  b.defects = b.defects || [];
  if(shipped >= 0.5) b.defects.push({ turn: S.turn + 3 + R.int(0,3), q: shipped, at: S.turn });

  let surfaced = 0, oldest = 0;
  b.defects = (b.defects||[]).filter(function(d){
    if(d.turn > S.turn) return true;
    surfaced += d.q; if(!oldest) oldest = d.at; return false;
  });
  b.defectsQ = Math.round(surfaced);
  if(surfaced > 0){
    const unit = (T.basePrice||100000) * S.cumInfl * 0.30 * (CITY().payMult||1);
    const cost = Math.round(surfaced * unit);
    b.cash -= cost;
    b.warrantyQ = cost;
    const repHit = clamp(0.7 + surfaced/Math.max(20,(units||1))*7, 0, 9);
    b.rep = clamp(b.rep - repHit, 0, 100);
    b.notes.push('Defects from ' + (S.turn - oldest) + ' quarters ago have surfaced: ' +
      Math.round(surfaced) + ' units and ' + fmt(cost) + ' in warranty, returns and goodwill.');
    log('biz','Warranty claims have landed for work shipped ' + (S.turn - oldest) +
      ' quarters ago. ' + fmt(cost) + '. You sold it, they bought it, and then it broke.','bad');
  } else b.warrantyQ = 0;

  b.pendingDefects = Math.round((b.defects||[]).reduce(function(a,d){ return a + d.q; }, 0));
  /* what the bill will be when it lands, so the trap is visible before it closes */
  const u = (T.basePrice||100000) * S.cumInfl * 0.30 * (CITY().payMult||1);
  b.defectBill = Math.round(b.pendingDefects * u);
}
/* ===========================================================================
   Customers are a stock, and a rival is a rival

   Marketing used to be `1 + 0.35*(m/(m+250000))`: spend more, get more
   demand, instantly, forever, and stop spending and it all vanishes at once.
   Neither of those is true.

   Real demand is a base of customers that behaves like a stock:
     - it DECAYS by a retention rate, so stopping spend loses you people
       gradually rather than all at once
     - you can ADD to it by buying customers, but CAC rises as you saturate
       the market you are fishing in
     - and above a quality threshold it grows on its own, because people tell
       each other - the only channel that compounds

   And a price cut is not an act in a vacuum: a rival with any aggression in
   them matches it, a quarter or two later, and takes back part of what you
   bought. Which is why "competing on price is a race you win by being the
   one willing to earn least" is a line in this game and not a slogan.
   =========================================================================== */
function stepCustomers(b){
  const T = BIZ.find(x=>x.id===b.type);
  if(b.custBase === undefined)
    b.custBase = Math.max(25, Math.round((b.revenue||0) / Math.max(1,(T.basePrice||100000)*S.cumInfl) * 0.6));
  /* ~10% a quarter at average quality and service. Higher than that and no
     level of spending can hold a base together; lower and retention stops
     being a thing you have to manage at all. */
  const qualRet  = clamp(0.93 + ((b.quality||50) - 50)/260, 0.82, 0.99);
  const svcRet   = clamp(0.97 + (((b.serviceQ===undefined?0.85:b.serviceQ) - 0.85)*0.05), 0.94, 0.995);
  const priceRet = clamp(1.0 - (b.discountMemory||0)*0.035, 0.95, 1.0);
  const churn    = 1 - clamp(qualRet*svcRet*priceRet, 0.42, 0.985);
  b.churnQ = churn;
  b.custBase = Math.max(0, b.custBase * (1 - churn));

  /* paid acquisition, with CAC rising as the pool fills up */
  const mkt = b.marketing||0;
  const marketSz = Math.max(1, 1250 * Math.pow(Math.max(0.2, outletScale(b)), 0.80) * S.mkt.demand);
  const satur = clamp(b.custBase / Math.max(1, marketSz*2.6), 0, 1.5);
  const cac   = Math.max(1, (T.basePrice||100000) * S.cumInfl * (0.55 + satur*2.2) * (CITY().payMult||1));
  const bought = mkt / cac;
  /* word of mouth: only above a quality threshold, and it compounds */
  const wom = (b.quality||50) > 58
    ? clamp(((b.quality||50)-58)/300 + (b.rep||45)/1400, 0, 0.10) : 0;
  const referred = b.custBase * wom;
  b.custBase = Math.max(0, b.custBase + bought + referred);
  b.cacQ = Math.round(cac); b.boughtQ = Math.round(bought);
  b.referredQ = Math.round(referred); b.womQ = wom;
}
function stepCompetitor(b){
  if(!S.rival){ b.rivalCut = (b.rivalCut||0)*0.80; return; }
  const band = priceBand(b);
  /* how far below your own station you are selling is what they notice */
  const aggressive = Math.max(0, band.lo - (b.priceIdx||1));
  const target = clamp(aggressive*1.7 + (S.rival.aggro||30)/300, 0, 0.60);
  b.rivalCut = (b.rivalCut||0)*0.62 + target*0.38;      // they take a quarter or two to move
  if(b.rivalCut > 0.14 && (b.quality||50) < 64)
    b.notes.push('Your rival has matched your price. You bought this volume once; holding it means cutting again.');
}
function bizDemand(b){
  const T = BIZ.find(x=>x.id===b.type), m = S.mkt;
  const marketSize = 1250 * Math.pow(Math.max(0.2, outletScale(b)), 0.80) * m.demand;
  const repF  = 0.15 + Math.pow(b.rep/100, 1.6)*1.35;   // reputation is the whole pipeline
  const _band = priceBand(b);
  const _over  = Math.max(0, (b.priceIdx||1) - _band.hi) / Math.max(0.2, _band.hi);
  const _under = Math.max(0, _band.lo - (b.priceIdx||1)) / Math.max(0.2, _band.lo);
  /* Raising price after a history of cuts is not the same act as raising it
     from a standing start: the market learned to wait for the sale, and it
     punishes the climb far harder than it rewarded the slide. That asymmetry
     is most of what real pricing is. */
  const _raising = !!b.priceRaising;
  const _mem = (b.discountMemory||0);
  const _elast = T.elasticity * (1 + _mem * (_raising ? 1.15 : -0.12));
  /* The climb back. This is the whole asymmetry: elasticity alone would hand
     you the volume straight back, because it only knows the level. Customers
     know the history. They leave in proportion to how much you are asking
     them to unlearn. */
  const _climb = 1 - Math.min(0.55, (b.priceRise||0) * _mem * 1.6);
  const priceF= Math.max(0.10,
      Math.pow(1/Math.max(0.3,b.priceIdx), _elast)
      * (1 - _over*1.95)        // charging above your station: they simply go
      * (1 + _under*0.40*(1 - (b.rivalCut||0)))   // cheap sells once, and they match it
      * (1 - (b.rivalCut||0)*0.22)
      * _climb);
  const brandB= 1 + 0.50*(b.brand/(b.brand+400000));
  const cb = Math.max(0, b.custBase||0);
  const mktB  = 1 + 0.85*(cb / (cb + Math.max(40, marketSize*0.35)));  // the base, not the spend
  const qualF = (0.72 + b.quality/190) * (0.90 + outletAvgCond(b)/500);
  const ramp  = clamp(0.22 + (S.turn - b.foundedTurn)*0.13, 0.22, 1);  // finding customers takes time
  const credit= 1 + (b.creditTerms||0)*0.22;                            // selling on credit buys volume
  const contractF = 1 + ((b.contracts||[]).reduce(function(a,c){ return a + (c.bonus||0); }, 0));
  const incF  = 1 - Math.min(0.35, ((b.incidents||[]).filter(function(i){ return i.turns>0; }).length)*0.09);
  const govF  = 1 + (boardSkill(b,'network')-50)/900;      // a board that opens doors
  return marketSize * repF * priceF * brandB * mktB * (1+connBonus(b)) * qualF * ramp * credit * contractF * incF * govF * channelDemandMult(b);
}
function simBusiness(){
  if(!S.bizs || !S.bizs.length){
    if(S.biz && !S.bizs){ S.bizs = [S.biz]; }
    else return 0;
  }
  let total = 0;
  bizList().slice().forEach(function(b){
    total += simOneBiz(b) || 0;
  });
  return total;
}
function simOneBiz(b){
  if(!b) return 0;
  const T = BIZ.find(x=>x.id===b.type), m = S.mkt;
  const inflF = S.cumInfl / b.startInfl;
  b.notes = [];
  // marketing memory decays, brand builds
  b.mktCarry = (b.mktCarry||0)*0.55 + Math.min(1, b.marketing/250000)*0.35;
  b.brand = b.brand*(1-0.04) + b.marketing*0.16;
  stepCommitments(b);                    /* promises come due before anything else is computed */
  stepPriceMemory(b);                    /* and the market remembers what you charged last time */
  stepCustomers(b);                      /* customers are a stock that decays and can compound */
  stepCompetitor(b);                     /* and somebody else is watching your price */
  b.capacity = bizCapacity(b);
  b.outletNotes = stepOutlets(b);
  let demand = bizDemand(b);
  let units = Math.min(b.capacity, demand);
  let shortCash = false;
  if(b.cash < 0){ shortCash = true; units *= 0.78; b.notes.push('Working capital is negative — you could not stock up properly.'); b.rep = clamp(b.rep-2.5,0,100); }
  // service level: under-stock and you turn customers away even when demand is there
  const cover = staffCover(b);
  const coverF = cover>=1 ? 1.02 : (0.58 + cover*0.42);
  /* Stock you have not paid for is stock you do not have. The policy sets
     what you want; `funded` is what you could actually afford. */
  const funded = wcFunded(b, b.revenue);
  const service = clamp((0.70 + wcPolicy(b)*0.30 + (b.auto||0)/260) * coverF * (0.52 + funded*0.48), 0.30, 0.995);
  b.wcFunded = funded; b.serviceQ = service;
  if(funded < 0.75) b.notes.push('You could only fund ' + Math.round(funded*100) +
    '% of the stock this business needs. Customers are being served off an empty shelf.');
  if(cover < 0.75) b.notes.push('You are short-staffed across your units — '+Math.round(cover*100)+'% of what these units need. Customers are waiting.');
  stepQuality(b, units);                 /* defects are built now and discovered later */
  const lostToStock = units * (1-service);
  units *= service;
  const serviceFail = (1-service) > 0.11;      // a genuine service failure, not normal thinning
  if(serviceFail && lostToStock > Math.max(2, b.capacity*0.10)){
    b.notes.push('You ran out of stock with customers in front of you. '+Math.round(lostToStock)+' units of demand went elsewhere.');
  }
  // supplier confidence: stretch them too far and the goods stop arriving
  if((b.supplierConf!==undefined && b.supplierConf < 36) || (b.payable||0) > Math.max(1,b.revenue*0.85)){
    units *= 0.74;
    b.notes.push('Suppliers are supplying less. You have been stretching them and they have noticed.');
  }
  // incidents (a bad batch, a bad review) suppress demand for a while
  if((b.incidents||[]).length){
    const active = b.incidents.filter(function(i){ return i.turns>0; });
    if(active.length) b.notes.push('Lingering damage: ' + active.map(function(i){return i.name;}).join(', ') + '.');
  }
  units *= R.range(0.93,1.07);
  b.units = units; b.demand = demand;
  const age = Math.max(0, S.turn - b.foundedTurn);
  const unitPrice = T.basePrice * b.priceIdx * inflF * CITY().payMult;
  // working capital: you can only sell what you can afford to stock and fund
  const wcPerUnit = unitPrice * (T.wc||0.25);
  // What you can actually stock is funded three ways: your own cash, the equipment
  // you can borrow against, and — the big one — the credit your suppliers extend.
  // That last one is a relationship, and it is the first thing to disappear.
  const supplyBase = Math.max(0,b.cash) + 0.6*Math.max(0,b.capex)
    + (b.supplierConf===undefined?70:b.supplierConf)/100 * Math.max(0,(b.lastRevenue||b.revenue||0)) * (T.wc||0.25) * 1.4
    * clamp((b.supplierDays||30)/30, 0.4, 4.0);
  const wcUnits = wcPerUnit>0 ? supplyBase / wcPerUnit : 1e9;
  const ceilingUnits = ((T.ceiling/4)*inflF)/unitPrice * outletCount(b);   // a real ceiling, not a nominal one
  units = Math.min(units, wcUnits, ceilingUnits);
  let revenue = units * unitPrice;
  // contracted work sits on top of walk-in trade, at whatever margin you bid
  const cRev = contractRevenue(b);
  const cCost = contractCost(b);
  revenue += cRev;
  // competitors arrive. Your margin erodes unless you keep investing in quality.
  // Competitors arrive and your margin erodes with age. You buy it back by
  // investing in the product and in the machinery — that is what those levers are for.
  const compression = Math.min(0.12, age*0.0030);
  const defence = (b.quality-50)/380 + (b.auto||0)/520 + (b.brand||0)/Math.max(1, 4000000 + (b.revenue||0))*0.05;
  const effMargin = clamp(T.margin - compression + defence, 0.05, 0.92);
  let cogs = (revenue - cRev) * (1 - effMargin) * (1 + theftRate(b)) * supplyCogsMult(b) + cCost;
  // opex
  /* a second shift is paid for in wages and in goodwill, not in equipment */
  const salaries = Math.round(staffMonthly(b)*3*shiftWageMult(b));
  const rent = Math.round(outletRent(b) * inflF * CITY().payMult);
  const nOut = outletCount(b);
  // organisations accumulate overhead as they age unless somebody keeps cutting
  const overhead = Math.round(260000*nOut*inflF*CITY().payMult*0.6 + revenue*(0.032 + Math.min(0.028, age*0.0008)));
  const power = Math.round((1 - m.power/100) * T.power * 900000 * nOut * inflF * CITY().payMult*0.6);
  const quality = (b.qualitySpendMonthly||0)*3;
  const _chanCut = channelCut(b, revenue);
  let opex = salaries + rent + b.marketing + overhead + power + quality + _chanCut;
  let gross = revenue - cogs;
  // A management charge is a real cost here and real income at the holdco. It is
  // deductible down here — which is precisely why the revenue service cares how big it is.
  const _mgmtFee = Math.round(revenue * (((S.holdco && S.holdco.mgmt) ? (S.holdco.mgmt[b.id]||0) : 0)/100));
  if(_mgmtFee > 0){ opex += _mgmtFee; b.cash -= _mgmtFee; b.mgmtFeeQ = _mgmtFee; }
  else { b.mgmtFeeQ = 0; }
  let profitBeforeTax = gross - opex;
  let tax = 0;
  if(b.formal && profitBeforeTax > 0) tax = profitBeforeTax * (0.20 + (b.taxLoad||0));
  let profit = profitBeforeTax - tax;
  // rent + salaries must be paid even in a bad quarter
  b.cash += profit;
  bizDeep(b, revenue, profit, {salaries:salaries, cogs:cogs});
  b.revenue = Math.round(revenue); b.cogs = Math.round(cogs); b.opex = Math.round(opex);
  b.tax = Math.round(tax); b.profit = Math.round(profit);
  b.chanCutQ = _chanCut; b.cogsMultQ = supplyCogsMult(b);
  b.retained = Math.round((b.retained||0) + (b.profit||0));
  b.culture = Math.round(companyCulture(b));
  b.ccc = cccOf(b);
  allocateOutlets(b, b.revenue, b.cogs, b.opex, b.profit);
  const _dep = Math.round((b.capex||0)*0.05);
  const _int = Math.round((b.debt||0)*0.055);
  const _ebitda = Math.round(profitBeforeTax + _dep + _int);
  b.history.push({turn:S.turn, revenue:b.revenue, cogs:b.cogs, opex:b.opex, profit:b.profit,
    units:Math.round(units), gross:Math.round(gross), ebitda:_ebitda, dep:_dep, int:_int, tax:b.tax,
    cash:Math.round(b.cash), recv:Math.round(b.recv||0), inv:Math.round(b.inventory||0),
    pay:Math.round(b.payable||0), staff:(b.staff||[]).length, out:outletCount(b),
    cap:Math.round(b.capacity||0), dem:Math.round(demand||0), debt:Math.round(b.debt||0)});
  if(b.history.length>40) b.history.shift();
  b.capexQ  = Math.max(0, Math.round((b.capex||0) - (b._capexMark||0)));
  b._capexMark = Math.round(b.capex||0);
  b.capex12 = Math.round(Math.max(0,(b.capex12||0)*0.75 + (b.capexQ||0)));
  // reputation dynamics
  // Reputation is measured on what actually happened, and exactly one thing can
  // damage it per quarter. Running flat out and running out of stock are the
  // same event, not two.
  if(b.capacity>0 && units >= b.capacity*0.96){ b.rep = clamp(b.rep-1.5,0,100); b.notes.push('You sold out — customers were turned away.'); }
  else if(serviceFail && b.capacity>0 && units < b.capacity*0.88 && lostToStock > Math.max(2, b.capacity*0.08)){
    b.rep = clamp(b.rep-1.2,0,100);
  }
  else if(units < b.capacity*0.55 && b.capacity>20){ b.notes.push('Idle capacity. You are paying for output you are not selling.'); }
  b.rep = clamp(b.rep + (b.quality-50)*0.035 + (50-b.rep)*0.05, 0, 100);
  if(b.priceOver > 0.02){
    b.rep = clamp(b.rep - (1.2 + b.priceOver*9), 0, 100);
    b.notes.push('You are charging ' + Math.round((b.priceOver + 1)*100 - 100) +
      '% above what this business has earned the right to charge. People have noticed, and they are telling each other.');
  }
  if((b.discountMemory||0) > 0.45)
    b.notes.push('The market has learned to wait for your discounts. Putting prices back up will cost you more than the cuts ever bought.');
  // staff morale
  b.staff.forEach(s=>{
    const fair = marketSalary(s.skill);
    const ratio = s.salary/fair;
    const tr = traitOf(s.trait);
    const tenure = Math.min(7, (S.turn - (s.joined||S.turn))*0.28);
    const profitHit = profit<0 ? (profit < -(revenue||0)*0.15 ? -6 : -2.5) : 3;
    const shiftWear = leverActive(b,'shifts') ? -3.2 : 0;   /* nights, weekends, and the people who stop coming */
    let dm = (ratio-1)*16 + profitHit + (ownerTimeEff()*2) + tenure - (b.staff.length>9?1.2:0) + shiftWear + R.gauss(0,3);
    s.morale = clamp(s.morale + dm, 3, 100);
    s.loyalty = clamp((s.loyalty||50) + (tr.loyalty||0)*0.12 + (ratio>1.05?1.5:-1.2), 0, 100);
  });
  // attrition
  const quitters = [];
  b.staff.forEach(s=>{
    /* Nobody quits in the quarter they joined. They have just negotiated,
       signed and served nothing; more to the point, you paid a recruitment
       fee for them, and having them vanish before they are ever on the
       payroll meant hiring was a coin flip in any mediocre firm. */
    if((S.turn - (s.joined||S.turn)) < 1) return;
    const tr = traitOf(s.trait);
    const tenureHold = Math.min(0.06, (S.turn-(s.joined||S.turn))*0.006);
    let p = 0.018 + (s.morale<32?0.16:0) + (100-(s.loyalty||50))/1400 + (s.salary<marketSalary(s.skill)*0.85?0.10:0) - tenureHold;
    // people who are happy and well paid are not quietly updating their CVs
    if(s.morale > 68) p *= 0.38;
    if(s.salary > marketSalary(s.skill)*1.08) p *= 0.60;
    if((b.staffTrust||55) > 70) p *= 0.72;
    p = clamp(p, 0, 0.42);
    if(R.chance(p)) quitters.push(s);
  });
  quitters.forEach(s=>{ b.staff = b.staff.filter(x=>x.id!==s.id);
    b.notes.push(s.name+' resigned.'); log('biz', s.name+' left '+b.name+'. '+(s.morale<30?'You saw it coming.':'You did not see it coming.'), 'warn'); });
  b.morale = b.staff.length ? Math.round(b.staff.reduce((a,s)=>a+s.morale,0)/b.staff.length) : 65;
  // owner skill accumulation
  S.p.skills.ops = clamp(S.p.skills.ops + (b.staff.length>0?0.9:0.5) + (profit>0?0.5:0.2), 0, 100);
  S.p.skills.finance = clamp(S.p.skills.finance + (revenue>0?0.4:0), 0, 100);
  // collapse check — one company dying does not take the rest with it
  if(b.cash < -Math.max(2000000, b.revenue*0.9) && R.chance(0.5)){
    closeBiz('The debts outran the business.', b);
    return 0;
  }
  return b.profit;
}
/* ---------------------- the deep operating model --------------------------- */
/* Everything below runs after the headline P&L is booked. It is the difference
   between a business that shows a profit and a business that has money.        */
/* ===========================================================================
   Working capital and the cash conversion cycle

   The counterintuitive lesson: profitable companies go bust because they are
   growing. Every naira of new revenue has to be financed - as stock before it
   is sold, as a receivable after it is - and the cash leaves quarters before
   the profit arrives. The cycle is:

       DSO (days sales outstanding) + DIO (days inventory) - DPO (days payables)
       = CCC, the number of days your cash is stuck inside the business.

   Grow by X% and you must fund X% more cycle, today. That bill is not on the
   P&L. It is the single most common way a real business dies, and until now
   it was invisible: service level depended on the stock *setting* rather than
   on whether the stock had actually been paid for, so a business that could
   not fund its inventory still served every customer who walked in.
   =========================================================================== */
function wcPolicy(b){ return b.stockPolicy===undefined ? 0.45 : b.stockPolicy; }
function wcTargetInv(b, revenue){
  const T = BIZ.find(x=>x.id===b.type);
  return Math.max(0, (revenue||0) * (T.wc||0.25) * (0.35 + wcPolicy(b)*1.5));
}
function wcCollectRate(b){
  return clamp(0.55 + (b.compliance||40)/280 +
    ((b.staff||[]).some(function(x){ return x.trait==='connected'; }) ? 0.08 : 0)
    - (S.mkt.demand<0.85 ? 0.10 : 0) - ((b.creditTerms||0)>0.7 ? 0.10 : 0), 0.22, 0.96);
}
const WC_DAYS = 91;                                   // a quarter
function cccOf(b){
  const rev  = Math.max(1, (b.revenue||0));
  const cogs = Math.max(1, (b.cogs||0));
  /* rounded first, then summed: the parts on screen have to add up to the
     whole on screen, or the player does the arithmetic and stops trusting it */
  const dso = Math.round((b.recv||0)      / rev  * WC_DAYS);
  const dio = Math.round((b.inventory||0) / cogs * WC_DAYS);
  const dpo = Math.round((b.payable||0)   / cogs * WC_DAYS);
  const ccc = dso + dio - dpo;
  return { dso:dso, dio:dio, dpo:dpo, ccc:ccc,
           tied: Math.round(Math.max(0, (b.recv||0) + (b.inventory||0) - (b.payable||0))) };
}
/* The bill for a quarter of growth, in cash, before any of it comes back.
   This is the number a growing business does not see coming. */
function growthBill(b, g){
  const T = BIZ.find(x=>x.id===b.type);
  const dRev = Math.max(0, (b.revenue||0) * (g||0));
  const recvDrag = dRev * clamp((b.creditTerms||0)*0.85, 0, 0.80) * (1 - wcCollectRate(b));
  const invDrag  = dRev * (T.wc||0.25) * (0.35 + wcPolicy(b)*1.5);
  const supFund  = invDrag * 0.25;                    // suppliers fund part of the stock
  return Math.round(Math.max(0, recvDrag + invDrag - supFund));
}
/* How much of the stock you want you could actually pay for. Nothing else in
   the model punished a business for not funding its own inventory. */
function wcFunded(b, revenue){
  const target = wcTargetInv(b, revenue);
  if(target <= 0) return 1;
  return clamp((b.inventory||0) / target, 0, 1);
}
function bizDeep(b, revenue, profit, ctx){
  const T = BIZ.find(x=>x.id===b.type);
  b.quarters = (b.quarters||0) + 1;
  if(profit>0) b.everProfitable = (b.everProfitable||0)+1;
  b.lastRevenue = b.revenue;
  const inflF = S.cumInfl / b.startInfl;

  /* --- 1. Receivables. Selling on credit buys volume and defers cash. ------- */
  const creditShare = clamp((b.creditTerms||0) * 0.85, 0, 0.80);
  const newRecv = Math.max(0, revenue * creditShare);
  b.recv = (b.recv||0) + newRecv;
  const collectRate = wcCollectRate(b);
  const collected = b.recv * collectRate;
  b.recv -= collected;
  const writeOff = b.recv * clamp(0.020 + (1-collectRate)*0.16, 0.01, 0.14);
  b.recv = Math.max(0, b.recv - writeOff);
  b.badDebtQ = Math.round(writeOff);
  b.cash -= newRecv;      // credit sales are not cash this quarter
  b.cash += collected;    // this quarter's collections are
  b.cash -= writeOff;     // and some of it never arrives

  /* --- 2. Inventory. Stock is cash that has stopped being liquid. ----------- */
  const targetInv = wcTargetInv(b, revenue);
  const invGap = targetInv - (b.inventory||0);
  if(invGap > 0){
    const buy = Math.min(invGap, Math.max(0, b.cash*0.75));
    b.inventory = (b.inventory||0) + buy; b.cash -= buy;
  } else {
    const release = Math.min(-invGap, (b.inventory||0), Math.max(0, revenue*(T.wc||0.25)*0.5));
    b.inventory = (b.inventory||0) - release; b.cash += release*0.9;   // you rarely sell stock back at cost
  }
  // spoilage / shrinkage / obsolescence
  const shrink = (b.inventory||0) * clamp(0.012 + theftRate()*1.4 + (T.id==='food'?0.030:T.id==='agri'?0.026:0.008), 0, 0.10);
  b.inventory = Math.max(0, (b.inventory||0) - shrink);
  b.shrinkQ = Math.round(shrink);

  /* --- 3. Payables. The free loan suppliers give you, until they don't. ----- */
  if(b.cash < 0){
    const stretch = Math.min(-b.cash, Math.max(0, cogsSafe(ctx)*0.60));
    if(stretch > 0){
      b.payable = (b.payable||0) + stretch; b.cash += stretch;
      b.supplierConf = clamp((b.supplierConf===undefined?70:b.supplierConf) - (5 + stretch/Math.max(1,revenue)*22), 0, 100);
      b.notes.push('You stretched suppliers by '+fmt(Math.round(stretch))+' to make the week.');
    }
  } else {
    const pay = Math.min((b.payable||0), b.cash*0.45);
    b.payable = (b.payable||0) - pay; b.cash -= pay;
    b.supplierConf = clamp((b.supplierConf===undefined?70:b.supplierConf) + (pay>0?4:0) + 1.2, 0, 100);
  }
  // suppliers cut you off
  if(b.supplierConf < 22 && R.chance(0.35)){
    b.payable = Math.max(0, b.payable*0.5);
    b.cash -= Math.round(Math.max(0, revenue*0.10));
    b.notes.push('A key supplier has stopped supplying until the account is settled. You had to buy spot, at spot prices.');
    log('biz','A supplier cut you off. Buying spot is more expensive, which is the point.','bad');
    b.supplierConf = clamp(b.supplierConf+12,0,100);
  }

  /* --- 4. Wages. If you miss payroll, the business changes character. ------- */
  const wageBill = (ctx && ctx.salaries) || staffMonthly(b)*3;
  if(wageBill > 0 && b.cash < wageBill*0.5){
    const shortfall = wageBill - Math.max(0, b.cash*0.9);
    b.arrears = (b.arrears||0) + Math.max(0, shortfall);
    b.staff.forEach(function(x){ x.morale = clamp(x.morale - 14, 3, 100); x.loyalty = clamp(x.loyalty-12,0,100); });
    b.staffTrust = clamp((b.staffTrust===undefined?55:b.staffTrust) - 16, 0, 100);
    b.notes.push('You could not pay salaries in full. Everyone knows by the next morning.');
    log('biz','You missed payroll at '+b.name+'. Arrears now '+fmt(Math.round(b.arrears||0))+'.','bad');
  } else if((b.arrears||0) > 0){
    const clear = Math.min(b.arrears, Math.max(0, b.cash*0.4));
    b.arrears -= clear; b.cash -= clear;
    if(clear>0){ b.staffTrust = clamp(b.staffTrust+8,0,100); b.staff.forEach(function(x){ x.morale = clamp(x.morale+6,3,100); }); }
  }

  /* --- 5. Owner draw. Taking money out is a decision, not a reward. --------- */
  const want = Math.max(0, b.draw||0);
  if(want > 0){
    const take = Math.min(want, Math.max(0, b.cash));
    b.cash -= take; S.fin.cash += take;
    b.drawnQ = Math.round(take);
    if(take>0) b.notes.push('You drew '+fmt(Math.round(take))+' out of the business this quarter.');
    if(take < want*0.5) b.notes.push('The business could not fund the draw you asked for.');
  } else b.drawnQ = 0;

  /* --- 6. Compliance, tax and the state. ----------------------------------- */
  if(b.formal){
    const bookkeeping = clamp(28 + (b.staff.some(function(x){return x.skill>=6;})?18:0) + S.p.skills.finance*0.34
                        + (b.auto||0)*0.12 - b.locations*3 - b.products*2, 5, 95);
    b.compliance = clamp((b.compliance||40) + (bookkeeping - (b.compliance||40))*0.22 + R.gauss(0,1.6), 0, 100);
    b.taxRisk = clamp((b.taxRisk||0) + (52 - b.compliance)*0.09 + (revenue>Math.max(1,b.lastRevenue*1.8)?9:0) - 1.5, 0, 100);
  } else {
    b.compliance = clamp((b.compliance||40) - 0.4, 0, 100);
    b.taxRisk = clamp((b.taxRisk||0) + (revenue>20000000?3.4:1.2) - 1.0, 0, 100);
  }
  /* Your own accountant works across every company you own; that is the point of having one. */
  const _acctTax = clamp(staffSupport('tax'), 0, 22), _acctCom = clamp(staffSupport('compliance'), 0, 20);
  if(_acctTax>0) b.taxRisk    = clamp((b.taxRisk||0)    - _acctTax*0.34, 0, 100);
  if(_acctCom>0) b.compliance = clamp((b.compliance||40)+ _acctCom*0.45, 0, 100);
  /* Benefit in kind: your own household staff sitting on the company payroll. */
  const _bikHidden = (S.house||[]).filter(function(h){ return h.payer===b.id && !h.declared; });
  if(_bikHidden.length){
    b.taxRisk = clamp((b.taxRisk||0) + _bikHidden.length*1.8, 0, 100);
    b.notes.push(_bikHidden.length+' member'+(_bikHidden.length>1?'s':'')+' of your household staff '+
      (_bikHidden.length>1?'are':'is')+' on this company payroll and not declared as a benefit in kind. '+
      'That is a tax exposure sitting there with your name on it.');
  }
  if(b.taxRisk > 78 && !S.flags.auditDue && R.chance(0.35)){ S.flags.auditDue = true; }
  // informal businesses get shaken down; formal ones get assessed
  if(!b.formal && revenue > 12000000 && R.chance(0.10 * (D().heat||1))){
    const ask = Math.round(Math.max(120000, revenue*0.018)*inflF);
    b.cash -= ask; b.notes.push('An inspector came by. '+fmt(ask)+' settled it informally.');
    log('biz','A visit from the local authority. '+fmt(ask)+' and it went away.','warn');
  }

  /* --- 7. Leases are handled per unit in stepOutlets(); surface the notes. --- */
  b.lease = (b.outlets && b.outlets[0]) || b.lease || null;
  (b.outletNotes||[]).forEach(function(n){
    log('biz', n.text, n.level==='bad'?'bad':'warn');
    if(n.level==='bad') S.flags.mustRelocate = true;
    b.notes.push(n.text);
  });

  /* --- 8. Key client concentration. ---------------------------------------- */
  if(b.keyClient){
    b.keyClient.turns = (b.keyClient.turns||0) - 1;
    b.keyClient.share = clamp(b.keyClient.share + R.gauss(0,0.02), 0.03, 0.75);
  } else if(b.quarters > 5 && revenue > 8000000 && R.chance(0.09)){
    b.keyClient = {name:R.pick(['a supermarket chain','a government MDA','a telco','a hotel group','an oil services firm','a church organisation','a school group','a diaspora buyer']),
      share:R.range(0.18,0.42), turns:R.int(4,10), payDays:R.int(30,120)};
    log('biz', b.keyClient.name+' has become a serious share of your revenue. That is good news with an expiry date.','warn');
  }

  /* --- 9. Incidents decay. -------------------------------------------------- */
  if(b.incidents && b.incidents.length){
    b.incidents.forEach(function(i){ i.turns -= 1; });
    b.incidents = b.incidents.filter(function(i){ return i.turns>0; });
  }

  /* --- 10. Contracts run, pay late, and go wrong. --------------------------- */
  if(b.contracts && b.contracts.length){
    (b.contracts||[]).forEach(function(c){
      if(!c.value) return;
      // contracted revenue arrives on the client's terms, not yours
      const days = Math.max(0, c.payDays||30);
      const onTime = clamp(1 - days/150, 0.05, 1);
      // The P&L already booked this revenue and its cost. All that happens here
      // is the timing: whatever the client has not paid yet becomes a receivable.
      const gross = c.value;
      b.cash -= Math.round(gross*(1-onTime));
      b.recv = (b.recv||0) + Math.round(gross*(1-onTime));
    });
    const cNotes = stepContracts(b);
    cNotes.forEach(function(n){ log('biz', n.text, n.level==='bad'?'bad':'warn'); b.notes.push(n.text); });
  }

  b.diag = bizDiag(b);
  b.stage = bizStage(b);
}
function cogsSafe(ctx){ return (ctx && ctx.cogs) || Math.max(0, (S.biz&&S.biz.cogs)||0); }

/* --------------------------- lifecycle + diagnosis -------------------------- */
function bizStage(b){
  if(!b) return 'none';
  const age = Math.max(0, S.turn - b.foundedTurn);
  const rev = b.revenue||0;
  if(age < 5 || rev < 1500000) return 'startup';
  if((b.everProfitable||0) < 3) return 'survival';
  if(b.locations<=1 && rev < 60000000) return 'traction';
  if(rev < (b.lastRevenue||0)*1.35 && (b.everProfitable||0) > 8 && age > 26) return 'decline';
  if(b.locations>=3 || rev > 250000000) return 'scale';
  return 'maturity';
}
/** @type {BIZ_STAGESShape2} */
const BIZ_STAGES = {
  startup:  {label:'Startup',   note:'You are still finding out whether anyone wants this.'},
  survival: {label:'Survival',  note:'It exists. It has not yet proven it can pay for itself.'},
  traction: {label:'Traction',  note:'Something is working. Now the constraint is you.'},
  scale:    {label:'Scale',     note:'Growth is the main risk now. Growth breaks things.'},
  maturity: {label:'Maturity',  note:'It makes money. The question is for how much longer.'},
  decline:  {label:'Decline',   note:'Revenue is going the wrong way and it is not the market.'}
};
function bizDiag(b){
  const out = []; if(!b) return out;
  const rev = Math.max(1, b.revenue||0);
  const push = (lvl,txt,key)=>out.push({level:lvl, text:txt, key:key});
  // receivables
  const recvQ = (b.recv||0)/rev;
  if(recvQ > 1.1) push('bad','You are owed '+fmt(Math.round(b.recv))+' — '+recvQ.toFixed(1)+' quarters of revenue. You are financing your customers.','recv');
  else if(recvQ > 0.6) push('warn','Receivables are '+recvQ.toFixed(1)+' quarters of revenue. Watch the ageing.','recv');
  if((b.badDebtQ||0) > rev*0.03) push('warn','You wrote off '+fmt(b.badDebtQ)+' in bad debt this quarter.','recv');
  // payables
  const payQ = (b.payable||0)/rev;
  if(payQ > 0.8) push('bad','You owe suppliers '+fmt(Math.round(b.payable))+'. They are close to cutting you off.','pay');
  else if((b.supplierConf!==undefined && b.supplierConf<45)) push('warn','Supplier confidence is '+Math.round(b.supplierConf)+'/100. They are watching the account.','pay');
  // inventory
  const invQ = (b.inventory||0)/rev;
  if(invQ > 1.4) push('warn','Inventory is '+invQ.toFixed(1)+' quarters of revenue sitting on a shelf.','inv');
  if((b.shrinkQ||0) > rev*0.018) push('warn','Shrinkage and spoilage cost '+fmt(b.shrinkQ)+' this quarter. Some of that is theft.','inv');
  // labour
  if(b.arrears>0) push('bad','You owe '+fmt(Math.round(b.arrears))+' in unpaid wages.','people');
  if(b.morale<35 && b.staff.length) push('bad','Morale is '+Math.round(b.morale)+'. People are updating their CVs.','people');
  else if(b.morale<50 && b.staff.length) push('warn','Morale is '+Math.round(b.morale)+'. Not a crisis yet.','people');
  if(b.staff.length===0 && b.locations>=1) push('warn','You are doing everything yourself.','people');
  // concentration
  if(b.keyClient && b.keyClient.share>0.30) push('warn','One customer ('+b.keyClient.name+') is about '+Math.round(b.keyClient.share*100)+'% of revenue.','conc');
  // cost structure
  const rentQ = (b.lease && b.lease.rent ? b.lease.rent*3 : 0);
  if(rentQ/rev > 0.18) push('warn','Rent is '+Math.round(rentQ/rev*100)+'% of revenue.','cost');
  const wageShare = (staffMonthly()*3)/rev;
  if(wageShare > 0.35) push('warn','Wages are '+Math.round(wageShare*100)+'% of revenue.','cost');
  // cash
  const runway = (b.cash||0) / Math.max(1, Math.max(0,(b.opex||0))*0.8);
  if((b.cash||0) < 0) push('bad','The company is cash-negative by '+fmt(Math.round(-b.cash))+'.','cash');
  else if(runway < 1) push('bad','You have under one quarter of operating cash left.','cash');
  // compliance
  if(b.taxRisk > 70) push('bad','Tax exposure is high. An assessment is likely.','tax');
  else if(b.compliance < 30 && b.formal) push('warn','Your books would not survive a serious look.','tax');
  // capacity
  if(b.capacity>0 && (b.units||0) < b.capacity*0.5) push('warn','You are running at '+Math.round((b.units||0)/Math.max(1,b.capacity)*100)+'% of capacity.','ops');
  if(b.capacity>0 && (b.units||0) > b.capacity*0.95) push('warn','You are at capacity. Demand is being turned away.','ops');
  return out;
}

function genCandidate(qualityBoost){
  const boost = qualityBoost||0;
  const skill = Math.round(clamp(R.gauss(4.6 + boost + S.p.rep/60, 1.9), 1, 10));
  const trait = R.weighted(TRAITS, t=>{
    if(t.id==='genius') return 0.5 + boost*0.3;
    if(t.id==='thief') return 1.0;
    if(t.id==='lazy') return 1.2;
    if(t.id==='loyal') return 1.1;
    return 1.6;
  }) || TRAITS[6];
  const sal = Math.round(marketSalary(skill) * (1 + (trait.salary||0)) * R.range(0.9,1.16));
  return { id:'s'+(++S.seq), name:R.pick(FIRST)+' '+R.pick(LAST), skill:skill, trait:trait.id,
           salary:sal, ask:Math.round(sal*R.range(1.05,1.30)),
           role:R.weighted(['ops','sales','support','finance'],function(x){ return x==='ops'?1.4:x==='sales'?1.2:x==='support'?1.0:0.5; })||'ops',
           outlet:null, trained:0, title:R.pick(['Officer','Assistant','Associate','Executive']),
           morale:clamp(62+R.gauss(0,10),20,95), loyalty:clamp(48+(trait.loyal||0)*0.5+R.gauss(0,12),5,98),
           joined:S.turn };
}
/** @type {STAFF_ROLESShape2} */
const STAFF_ROLES = {
  ops:     {label:'Operations',  note:'Produces the thing you sell.'},
  sales:   {label:'Sales',       note:'Brings demand in. +10% effectiveness.'},
  support: {label:'Support',     note:'Admin, stores, front of house.'},
  finance: {label:'Finance',     note:'Improves the books and reduces tax risk.'},
  gm:      {label:'General manager', note:'Runs the unit without you. Frees your attention for other companies.'}
};
function staffSkillAvg(b){ const st=(b&&b.staff)||[]; return st.length? st.reduce(function(a,x){return a+x.skill;},0)/st.length : 0; }

/* =========================================================================
   The household - staff you employ for your own life
   -------------------------------------------------------------------------
   Nobody puts these people on an organogram. They are the reason you can be
   in two places, why the house works, and why you are not cooking at eleven
   at night before a board meeting. They also cost money every single month,
   they drift like any employee, and the good ones are the only thing in this
   game that gives you back hours rather than taking them.
   ========================================================================= */
/** @type {HOUSE_ROLESShape19} */
const HOUSE_ROLES = {
  cleaner:  {label:'Housekeeper', tier:'home', pay:0.55, req:null,
    note:'The house stops being a second job. Nothing dramatic, every single week.',
    fx:{calm:1.7, joy:0.8, time:0.03}},
  cook:     {label:'Cook', tier:'home', pay:0.72, req:null,
    note:'You eat properly and at the same hour. It turns up in your bloodwork a decade later.',
    fx:{health:2.6, joy:1.3, calm:1.1}},
  nanny:    {label:'Nanny', tier:'home', pay:0.80, req:'kids',
    note:'Childcare that is not you at two in the morning. The largest single block of attention you can buy.',
    fx:{calm:2.3, family:2.8, time:0.16}},
  driver:   {label:'Driver', tier:'home', pay:0.95, req:null,
    note:'Traffic stops being your job. You arrive composed and you work in the back seat.',
    fx:{time:0.13, calm:1.5, status:1.2}},
  gardener: {label:'Gardener', tier:'home', pay:0.45, req:'assets',
    note:'Grounds, generator, gutters. Property upkeep falls and the place looks like somebody owns it.',
    fx:{upkeep:0.18, joy:0.9, status:0.4}},
  security: {label:'Security', tier:'home', pay:0.62, req:null,
    note:'A gate and a man on it. Cuts theft at home and, if you post him there, at the business.',
    fx:{calm:1.6, secure:1.0, status:0.6}},
  pa:       {label:'Personal assistant', tier:'exec', pay:1.15, req:null,
    note:'Your calendar, your calls, the birthday you always forget. The best return on attention on this list.',
    fx:{time:0.20, calm:2.1, status:1.0}},
  cos:      {label:'Chief of staff', tier:'exec', pay:2.25, req:'biz',
    note:'Runs your affairs across every company you own. Partly covers businesses that have no general manager.',
    fx:{time:0.26, calm:1.7, gmCover:1.0}},
  acct:     {label:'Accountant', tier:'exec', pay:1.60, req:null,
    note:'Books kept properly across the companies and your own affairs. Tax exposure falls, compliance rises.',
    fx:{tax:5.5, compliance:5.0}},
  lawyer:   {label:'Lawyer', tier:'exec', pay:1.95, req:null,
    note:'Reads what you are about to sign. Contracts tighten and disputes cost less when they arrive.',
    fx:{legal:1.0, compliance:3.0}}
};
/** @type {HOUSE_PERKSShape2} */
const HOUSE_PERKS = {
  housing:   {label:'Accommodation', cost:0.18, morale:6, loyalty:5, note:'They live in. Cheaper than the equivalent allowance, and they are always there.'},
  transport: {label:'Transport',     cost:0.12, morale:3, loyalty:2, note:'You cover getting to work and back.'},
  feeding:   {label:'Feeding',       cost:0.10, morale:4, loyalty:3, note:'One proper meal a day on you.'},
  medical:   {label:'Medical',       cost:0.07, morale:2, loyalty:4, note:'A retainer at a clinic. They stop bringing you their problems.'},
  bonus:     {label:'13th month',    cost:0.09, morale:5, loyalty:7, note:'An extra month every December. The cheapest way to keep somebody through a hard year.'}
};
function houseRoleAvail(k){
  const R0 = HOUSE_ROLES[k]; if(!R0) return false;
  if(R0.req==='kids')   return (S.p.kids||0) > 0;
  if(R0.req==='assets') return ((S.assets||[]).length>0 || bizList().length>0);
  if(R0.req==='biz')    return bizList().length > 0;
  return true;
}
function houseBasePay(roleId){ const R0=HOUSE_ROLES[roleId]; return (R0?R0.pay:1) * 165000; }
function houseSalaryFor(roleId, skill){
  const R0 = HOUSE_ROLES[roleId]; if(!R0) return 0;
  const sk = 0.72 + (clamp(skill,1,10)/10)*0.62;   // 0.78x at skill 1, 1.34x at skill 10
  const talent = (S && S.tune) ? (S.tune.talent||1) : 1;
  return Math.max(30000, Math.round(houseBasePay(roleId) * sk * CITY().payMult * S.cumInfl * talent));
}
function housePerkCost(h){
  const pk = (h && h.perks) || {};
  return Object.keys(HOUSE_PERKS).reduce(function(a,k){
    return a + (pk[k] ? Math.round((h.salary||0)*HOUSE_PERKS[k].cost) : 0); },0);
}
function houseMonthly(){ return (S.house||[]).reduce(function(a,h){ return a+(h.salary||0)+housePerkCost(h); },0); }
function houseMonthlyYou(){
  return (S.house||[]).filter(function(h){ return (h.payer||'you')==='you'; })
    .reduce(function(a,h){ return a+(h.salary||0)+housePerkCost(h); },0);
}
/* Declared benefit in kind is grossed up for tax. Undeclared is cheaper today and is a
   liability with your name on it. That choice is the whole mechanic. */
function houseMonthlyBiz(bid){
  return (S.house||[]).filter(function(h){ return h.payer===bid; }).reduce(function(a,h){
    const c = (h.salary||0)+housePerkCost(h);
    return a + c + (h.declared ? Math.round(c*0.30) : 0);
  },0);
}
/* How much of what you hired them for you actually get. Skill, morale, tenure and
   performance all move it. A brilliant, miserable, three-week-old hire delivers very little. */
function houseQ(h){
  const skillF  = 0.42 + (clamp(h.skill,1,10)/10)*0.78 + (h.trained||0)*0.05;
  const moraleF = clamp(0.35 + ((h.morale===undefined?60:h.morale)/100)*0.95, 0.20, 1.15);
  const tenF    = 1 + Math.min(0.25, Math.max(0,(S.turn-(h.joined||S.turn)))/40);
  const perfF   = 0.70 + ((h.perf===undefined?60:h.perf)/100)*0.60;
  return clamp(skillF*moraleF*tenF*perfF, 0, 1.60);
}
function staffSupport(tag){
  return (S.house||[]).reduce(function(a,h){
    const R0 = HOUSE_ROLES[h.role]; if(!R0 || !R0.fx || !R0.fx[tag]) return a;
    return a + R0.fx[tag]*houseQ(h);
  },0);
}
/* Hours given back. This is the entire point of employing people for your own life. */
function houseTimeBoost(){ return clamp(staffSupport('time'), 0, 0.42); }
function ownerTimeEff(){
  const base = ownerTime();
  return clamp(base + houseTimeBoost(), 0, 1.30);
}
function gmCoverQ(){ return clamp(staffSupport('gmCover'), 0, 1); }

function genHouseCand(roleId){
  const R0 = HOUSE_ROLES[roleId]; if(!R0) return null;
  const skill = Math.round(clamp(R.gauss(4.2 + (S.p.rep||40)/70, 1.9), 1, 10));
  const trait = R.weighted(TRAITS, function(t){
    if(t.id==='genius') return 0.30;
    if(t.id==='thief')  return R0.tier==='home' ? 1.6 : 0.8;
    if(t.id==='lazy')   return 1.30;
    if(t.id==='loyal')  return 1.20;
    return 1.50;
  }) || TRAITS[6];
  const sal = houseSalaryFor(roleId, skill);
  return { id:'h'+(++S.seq), role:roleId, name:R.pick(FIRST)+' '+R.pick(LAST),
    skill:skill, trait:trait.id, salary:sal, ask:Math.round(sal*R.range(1.06,1.32)),
    morale:clamp(60+R.gauss(0,10),20,95), loyalty:clamp(46+(trait.loyal||0)*0.5+R.gauss(0,12),5,98),
    joined:S.turn, trained:0, perf:60, quarters:0, perks:{}, payer:'you', declared:false,
    suspicion:0, ref:R.pick(['a cousin of somebody who already works for you',
      'an agency that has sent you two bad ones already','a family you know from church',
      'a referral from a friend you trust','a card in a shop window']) };
}
function refreshHouseCands(){
  const avail = Object.keys(HOUSE_ROLES).filter(houseRoleAvail);
  if(!avail.length){ S.houseCands = []; return; }
  const n = clamp(2 + Math.floor(R.f()*3), 2, Math.min(5, avail.length));
  S.houseCands = R.pickN(avail, n).map(function(k){ return genHouseCand(k); }).filter(Boolean);
}
function hireHouse(c, salary, payer){
  c.salary  = Math.round(salary);
  c.payer   = payer || 'you';
  c.joined  = S.turn; c.morale = 68; c.perf = 60; c.quarters = 0;
  c.loyalty = clamp(c.loyalty, 20, 95);
  S.fin.cash -= Math.round(c.salary*0.5);            // finding and placing them costs something
  S.house = (S.house||[]).concat([c]);
  S.houseCands = (S.houseCands||[]).filter(function(x){ return x.id!==c.id; });
  const who = c.payer==='you' ? 'you' : ((bizById(c.payer)||{}).name || 'a company');
  log('life','You employed '+c.name+' as '+(HOUSE_ROLES[c.role]||{label:'staff'}).label.toLowerCase()+
    ' at '+fmt(c.salary)+' a month, paid by '+who+'.','neutral');
  return c;
}
function fireHouse(id, sev){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  const amount = Math.max(0, Math.round(sev||0));
  S.fin.cash -= amount;
  S.house = (S.house||[]).filter(function(x){ return x.id!==id; });
  S.house.forEach(function(o){ o.morale = clamp(o.morale-6,3,100); o.loyalty = clamp(o.loyalty-5,0,100); });
  log('life','You let '+h.name+' go. Severance '+fmt(amount)+'. The house is quieter and everybody else is watching.','warn');
  if(h.loyalty < 45 || h.morale < 40){
    S.p.rep = clamp(S.p.rep-1.2,0,100);
    log('life','People talk. A household that leaves unhappy takes your name with it.','warn');
  }
}
function houseTrain(id){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  const cost = Math.round((h.salary||0)*0.9);
  if(S.fin.cash < cost){ toast('Training costs '+fmt(cost)+'.'); return; }
  S.fin.cash -= cost; h.trained = (h.trained||0)+1;
  if((h.trained||0)%2===1) h.skill = clamp(h.skill+1,1,10);
  h.morale = clamp(h.morale+7,3,100); h.loyalty = clamp(h.loyalty+5,0,100);
  log('life','You paid for '+h.name+' to be trained properly. Skill is now '+h.skill+'/10.','good');
}
function houseRaise(id, pctv){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  h.salary = Math.round((h.salary||0)*(1+pctv));
  h.morale = clamp(h.morale+pctv*70,3,100); h.loyalty = clamp(h.loyalty+pctv*45,0,100);
  log('life','You raised '+h.name+' to '+fmt(h.salary)+' a month.','good');
}
function housePerkToggle(id, key){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  const P = HOUSE_PERKS[key]; if(!P) return;
  h.perks = h.perks||{};
  if(!h.perks[key]){ h.perks[key] = true;  h.morale = clamp(h.morale+P.morale,3,100);      h.loyalty = clamp(h.loyalty+P.loyalty,0,100); }
  else             { h.perks[key] = false; h.morale = clamp(h.morale-P.morale*0.8,3,100);  h.loyalty = clamp(h.loyalty-P.loyalty*0.5,0,100); }
}
function houseReassign(id, roleId){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  const R0 = HOUSE_ROLES[roleId]; if(!R0) return;
  h.role = roleId;
  h.salary = Math.max(h.salary||0, houseSalaryFor(roleId, h.skill));
  h.morale = clamp(h.morale-5,3,100);
  log('life','You moved '+h.name+' to '+R0.label.toLowerCase()+'. They will take a few months to be any good at it.','neutral');
}
function houseSetPayer(id, payerId){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  h.payer = payerId || 'you';
  if(h.payer==='you') h.declared = false;
  log('life',(HOUSE_ROLES[h.role]||{label:'Staff'}).label+' '+h.name+' is now paid by '+
    (h.payer==='you' ? 'you' : ((bizById(h.payer)||{}).name||'a company'))+'.','neutral');
}
function houseToggleDeclare(id){
  const h = (S.house||[]).find(function(x){ return x.id===id; }); if(!h) return;
  if((h.payer||'you')==='you') return;
  h.declared = !h.declared;
  log('life','Benefit in kind for '+h.name+' is now '+(h.declared?'declared and grossed up for tax':'left undeclared')+'.','warn');
}
/* One quarter of household life: pay, drift, loyalty, theft, and who walks out. */
function stepHouse(){
  const list = S.house||[];
  if(!list.length){ refreshHouseCands(); return; }
  let personalCost = 0;
  const quitters = [];
  list.forEach(function(h){
    const tr = traitOf(h.trait);
    h.quarters = (h.quarters||0)+1;
    const fair   = houseSalaryFor(h.role, h.skill);
    const ratioV = (h.salary||0)/Math.max(1,fair);
    const pk = h.perks||{};
    let perkM = 0;
    Object.keys(HOUSE_PERKS).forEach(function(k){ if(pk[k]) perkM += HOUSE_PERKS[k].morale*0.6; });
    const mTarget = 50 + (ratioV-1)*30 + perkM;                 // pay and conditions set the level
    h.morale  = clamp(h.morale + (mTarget - h.morale)*0.32 + R.gauss(0,4), 3, 100);
    h.loyalty = clamp(h.loyalty + ((ratioV-1)*16 + (pk.bonus?4:0) + (h.morale>62?2.2:-3.0))*0.5 + R.gauss(0,2.2), 0, 100);
    h.perf    = clamp(46 + h.skill*3.2 + (tr.output||0)*18 + (h.morale-60)*0.34 + (h.trained||0)*2.5 + R.gauss(0,7), 5, 99);
    // domestic staff are close to the money and close to everything you own
    if(tr.theft && R.chance(clamp(tr.theft*0.05*(h.morale<45?2.0:1.0),0,0.5))){
      const amt = Math.round(Math.min(Math.max(0,S.fin.cash)*0.06, (h.salary||0)*R.range(0.6,2.2)));
      if(amt>5000){
        S.fin.cash -= amt; h.suspicion = (h.suspicion||0)+1;
        log('life','Money has been going missing for weeks and you have known, in your gut, who it is. ('+fmt(amt)+')','bad');
      }
    }
    if((h.payer||'you')==='you') personalCost += Math.round(((h.salary||0)+housePerkCost(h))*3);
    /* Turnover. The base rate is low, but inflation raises the going rate every year,
       so a salary you never revisit quietly becomes an underpayment, and underpaid
       people leave. The pay review exists for exactly this reason. */
    const leave = clamp((ratioV<0.86?0.13:0.018) + (h.morale<32?0.14:0) + (h.loyalty<30?0.09:0)
                        - (h.loyalty>75?0.07:0) - ((h.quarters||0)<4?0.015:0), 0, 0.5);
    if((h.quarters||0)>0 && R.chance(leave*D().fail)) quitters.push(h);
  });
  if(personalCost>0){ S.fin.cash -= personalCost; tx('Household staff '+String.fromCharCode(8722)+fmt(personalCost)); }
  quitters.forEach(function(h){
    S.house = (S.house||[]).filter(function(x){ return x.id!==h.id; });
    log('life', h.name+' left. '+(h.morale<45
      ? 'They did not go quietly, and the version of you that now exists in other people is not one you would choose.'
      : 'You were not paying enough to keep them and both of you had known it for a while.'),'warn');
    if(h.morale<45) S.p.rep = clamp(S.p.rep-1.0,0,100);
    S.house.forEach(function(o){ o.morale = clamp(o.morale-4,3,100); });
  });
  refreshHouseCands();
}

function hasGM(b){ return !!(b && (b.staff||[]).some(function(x){ return x.role==='gm'; })); }
function outletStaff(b, oid){ return (b&&b.staff||[]).filter(function(x){ return x.outlet===oid; }); }
function promoteGM(b, sid){
  const st = (b&&b.staff||[]).find(function(x){ return x.id===sid; }); if(!st) return false;
  if((b.staff||[]).some(function(x){ return x.role==='gm'; })) return false;
  if(st.skill < 6) return false;
  const bump = Math.round(st.salary*0.55);
  st.role = 'gm'; st.salary += bump; st.morale = clamp(st.morale+22,3,100); st.loyalty = clamp(st.loyalty+20,0,100);
  log('biz', st.name+' becomes general manager of '+b.name+'. Pay up '+fmt(bump)+'/month, and you get your evenings back.','good');
  return true;
}
function trainStaff(b, sid, level){
  const st = (b&&b.staff||[]).find(function(x){ return x.id===sid; }); if(!st) return null;
  const cost = Math.round(st.salary*(level===2?7:2.6));
  if(b.cash < cost) return null;
  b.cash -= cost;
  const p = level===2 ? 0.62 : 0.34;
  if(st.skill>=10) return {ok:false, text:st.name+' is already at the top of the scale.'};
  if(R.chance(p)){
    st.skill = clamp(st.skill+1,1,10); st.trained = (st.trained||0)+1;
    st.morale = clamp(st.morale+9,3,100); st.loyalty = clamp(st.loyalty+8,0,100);
    log('biz','You paid for '+st.name+' to train. Skill is now '+st.skill+'/10.','good');
    return {ok:true, cost:cost, text:st.name+' came back better. Skill '+st.skill+'/10.'};
  }
  st.morale = clamp(st.morale+4,3,100);
  log('biz','You paid '+fmt(cost)+' towards training for '+st.name+'. It did not show up in the work.','neutral');
  return {ok:false, cost:cost, text:'The course did not take. '+st.name+' is grateful and no more skilled.'};
}
function hire(c){
  const b = S.biz, notice = 1;
  const fee = Math.round(c.salary*0.5);          // recruitment + first-month cost
  S.fin.cash -= fee;
  const st = Object.assign({}, c); st.morale = 68; st.loyalty = clamp(st.loyalty,20,95);
  /* They work a notice period before they arrive, and they are not useful the
     day they do. Both facts used to be free. */
  commitNew(b, { kind:'hire', label:'Hiring '+st.name, total:fee, paid:fee,
    lead:notice, breakPct:0.60, staff:st });
  log('biz','You offered '+st.name+' the job — skill '+st.skill+'/10, '+fmt(st.salary)+'/month. '+
    (traitOf(st.trait).name||'No particular trait')+'. They work their notice and join next quarter.','neutral');
}
function fire(id){
  const b=S.biz; const s=b.staff.find(x=>x.id===id); if(!s) return;
  if(s.leaving !== undefined) return;                  // already working notice
  const sev = Math.round(s.salary*(S.turn - (s.joined||S.turn) > 8 ? 2 : 1));
  S.fin.cash -= sev;
  /* They do not disappear. They work a notice period on your payroll, at
     reduced output, in front of everyone else. */
  s.leaving = S.turn + 1;
  b.staff.forEach(o=>{ if(o.id===id) return;
    o.morale = clamp(o.morale - 7, 3, 100); o.loyalty = clamp(o.loyalty-6,0,100); });
  b.rep = clamp(b.rep-1.5,0,100);
  log('biz','You gave '+s.name+' notice. Severance '+fmt(sev)+
    '. They are still on the payroll this quarter, and the room got quiet.','warn');
}
function giveRaise(id, pctv){
  const s=S.biz.staff.find(x=>x.id===id); if(!s) return;
  s.salary = Math.round(s.salary*(1+pctv)); s.morale = clamp(s.morale+pctv*70,3,100); s.loyalty = clamp(s.loyalty+pctv*45,0,100);
  log('biz','You raised '+s.name+'\'s pay by '+pct(pctv,0)+'. Morale jumped.','good');
}
function expandCost(){
  const b=S.biz, T=BIZ.find(x=>x.id===b.type);
  const cm = T.capex==='vhigh'?8 : T.capex==='high'?4.5 : T.capex==='med'?2.6 : 1.5;
  return Math.round(16000000 * cm * S.cumInfl * (1 + 0.35*Math.max(0,b.locations-1)));
}
function expandBiz(){
  const b=S.biz, T=BIZ.find(x=>x.id===b.type);
  const cost = expandCost();
  const dep  = Math.round(cost*0.35);
  if(S.fin.cash < dep){ toast('You need '+fmt(dep)+' up front to commit to another location.'); return false; }
  /* A location is not bought, it is committed to: a lease, a fit-out, a
     landlord, a hiring round. It takes quarters to arrive, it costs money
     the whole time, and abandoning it later costs most of what you have
     already spent. Lead time grows with distance from what you know. */
  const lead = 2 + ((b.locations||1) > 2 ? 1 : 0);
  S.fin.cash -= dep;
  commitNew(b, { kind:'unit', label:'Location #'+((b.locations||1)+1), total:cost,
    paid:dep, lead:lead, breakPct:0.30, city:S.city });
  log('biz','You committed to location #'+((b.locations||1)+1)+' — '+fmt(cost)+' all in, '+
    fmt(dep)+' now. Fit-out starts this quarter and it trades in about '+lead+
    ' quarters. Abandoning it later will cost you most of what you have already spent.','neutral');
  return true;
}
function formalizeBiz(){
  const b=S.biz; const cost = Math.round(450000*S.cumInfl);
  if(S.fin.cash<cost){ toast('Registration costs '+fmt(cost)+'.'); return false; }
  S.fin.cash -= cost; b.formal = true; b.rep = clamp(b.rep+6,0,100);
  S.fin.credit = clamp(S.fin.credit+5,0,100);
  log('biz','You registered the company. It costs you tax, and buys you access to banks, contracts and courts.','good');
  ensureGov(b);
  if(!(b.board||[]).some(function(d){ return !d.yours; })){
    log('biz','A registered company is supposed to have a board. You can fill the seats from the Governance tab, and whether you bother will be noticed.','neutral');
  }
  return true;
}
function drawFromBiz(amt){
  const b=S.biz; if(!b) return false;
  if(b.drawCap !== undefined && amt > b.drawCap){
    toast('The board capped your drawings at '+fmt(b.drawCap)+' a quarter.');
    amt = b.drawCap;
  }
  amt = Math.min(amt, Math.max(0, Math.floor(b.cash)));
  if(amt<=0){ toast('No distributable cash in the business.'); return false; }
  const net = Math.round(amt * (b.equity/100));
  b.cash -= amt; S.fin.cash += net;
  if(b.equity<100 && b.partner){ const theirs = amt - net; log('biz','You drew '+fmt(net)+'. '+b.partner.name+' took '+fmt(theirs)+'.','neutral'); }
  else log('biz','You paid yourself '+fmt(net)+' out of the business.','neutral');
  return true;
}
function injectBiz(amt){
  if(S.fin.cash < amt){ toast('Not enough cash.'); return false; }
  S.fin.cash -= amt; S.biz.cash += amt; S.biz.capex += Math.round(amt*0.4);
  log('biz','You put '+fmt(amt)+' of personal money into the business.','warn');
  return true;
}
function genPartnerOffer(){
  const capital = Math.round(R.range(0.6,2.4)*(S.biz? startBizCost(S.biz.type):3000000));
  const equity = Math.round(clamp(R.range(0.18,0.45),0.1,0.6)*100);
  return { id:'p'+(++S.seq), name:R.pick(FIRST)+' '+R.pick(LAST), capital:capital, equity:equity,
    skill:R.pick(['ops','finance','network','tech']), trust:Math.round(R.range(45,80)),
    bg:R.pick(['ex-banker with a book of clients','operator who has built and sold once','family money and a good surname','a hustler with distribution nobody else has','technical person who can actually build the thing']),
    ask: R.pick(['wants a board seat','wants monthly reporting','wants a signed founders agreement','wants their cousin on the payroll']) };
}
/* How many new shares carry `equityPct` of the company *after* they are
   issued. Getting this wrong by using the pre-issue total is the classic way
   to hand over more of a company than was agreed. */
function partnerSharesFor(b, equityPct){
  const e = clamp((equityPct||0)/100, 0.01, 0.60);
  const before = Math.max(1, totalShares(b));
  return Math.max(1, Math.round(before * e / (1 - e)));
}
/* Somebody buys into the company you already have.

   This is the promise the Deals card has been making since the partnership
   offers were written: capital in, equity out, and one thing they asked for
   minuted against you. The money lands in the company, not with you — which
   is the part people find out later. */
/* An offer can be sitting in S.offers (the Deals screen) or in the partner
   modal you are looking at. Two places to look for one thing is how the same
   bug shipped twice under the same button label. */
/* Addressed by id, not by position.

   With an index, the same click meant different things depending on which
   list happened to be checked first: with the partner modal open, index 0 was
   the modal's first offer, and a click aimed at the Deals screen silently
   acted on the wrong person. The id means one offer is one offer wherever it
   is showing. */
function offerById(id){
  const all = (S.offers || []).concat(((UI.modal && UI.modal.offers) || []));
  for (let i = 0; i < all.length; i++) if (all[i].id === id) return all[i];
  return null;
}
/* and one place that knows how to take one off the table, from wherever it is */
function offerRemove(o){
  const m = UI.modal;
  if (m && m.offers) m.offers = m.offers.filter(function(x){ return x.id !== o.id; });
  S.offers = (S.offers || []).filter(function(x){ return x.id !== o.id; });
  if (m && m.type === 'partner' && !(m.offers || []).length) UI.modal = null;   /* nothing left to look at */
}
function takePartner(id){
  const b = S.biz, o = offerById(id);
  if(!b){ toast('There is no company to bring anyone into'); return; }
  if(!o) return;
  const eq = clamp(o.equity||0, 5, 60);
  const n = partnerSharesFor(b, eq);
  const p = Math.max(1, Math.round((o.capital||0) / Math.max(1, n)));
  const before = Math.max(1, totalShares(b));
  const afterPct = Math.round(n / (before + n) * 100);
  confirmBox('Bring in ' + o.name,
    '<b>'+fmt(o.capital)+'</b> into the company for <b>'+afterPct+'%</b> of it.'+
    '<br><br>They bring <b>'+esc(o.skill)+'</b> and start at <b>'+(o.trust===undefined?60:o.trust)+
    '/100</b> trust. What they want in return: <b>'+esc(o.ask)+'</b>.'+
    '<hr class="sep"><span class="muted">The money lands in the company, not with you. '+
    'You are selling a share of everything this business ever earns, and the only way '+
    'to buy it back is at a premium that rises as their trust falls.</span>',
    function(){
      ensureGov(b);
      const wantsSeat = /board seat/i.test(o.ask||'');
      const h = addHolder(b, { name:o.name, kind:'partner', kindName:'Partner',
        cls:'Ordinary', trust:(o.trust===undefined?60:o.trust),
        board:wantsSeat, seat:wantsSeat, roundLabel:'Partnership' });
      h.ask = o.ask; h.skill = o.skill; h.cameInAt = S.turn;
      const raised = Math.round(n * p);
      issueTo(b, h, n, p);
      offerRemove(o);
      /* the ask is minuted, because it is the thing they will judge you on
         and the thing the Promises card will hold you to */
      const kind = /board seat/i.test(o.ask||'') ? 'seat'
                 : /reporting/i.test(o.ask||'')  ? 'reporting'
                 : /agreement/i.test(o.ask||'')  ? 'agreement'
                 : /payroll/i.test(o.ask||'')    ? 'job' : 'reporting';
      b.undertakings = b.undertakings || [];
      b.undertakings.push({ id:'u'+(++S.seq), kind:kind, text:o.ask, dirId:h.id, dirName:o.name,
        made:S.turn, due:S.turn + 4 });
      log('biz', o.name+' has come in for '+afterPct+'% with '+fmt(raised)+'. '+
        'You own '+b.equity+'% of it now. They asked for one thing and it is on the record.','good');
      pushNews(o.name+' joins as a partner','good');
      toast(o.name+' is in · '+afterPct+'%');
      render();
    }, 'Take the money');
}
function buyOutPartner(){
  const b=S.biz; if(!b) return false;
  ensureGov(b);
  if(!extHolders(b).length){ toast('There is nobody to buy out.'); return false; }
  const q = buyoutExternal(b, 1.30);
  const r = doBuyoutExternal(b, 1.30);
  if(!r){ toast('Buyout would cost about '+fmt(q.cost)+'. You have '+fmt(S.fin.cash)+'.'); return false; }
  log('biz','You bought out '+r.names+' for '+fmt(r.cost)+'. The register has one name on it again.','good');
  return true;
}

/* =========================================================================
   Section 7: Investments & goods
   ========================================================================= */
function buyAsset(id, amt){
  const d = ASSETS.find(x=>x.id===id); if(!d) return false;
  amt = Math.floor(amt);
  if(amt < d.min){ toast('Minimum for '+d.name+' is '+fmt(d.min)+'.'); return false; }
  if(amt > S.fin.cash){ toast('You only have '+fmt(S.fin.cash)+'.'); return false; }
  S.fin.cash -= amt;
  let h = S.assets.find(a=>a.id===id);
  if(h){ h.value += amt; h.cost += amt; } else { S.assets.push({id:id, value:amt, cost:amt, from:S.turn}); }
  log('invest','Bought '+fmt(amt)+' of '+d.name+'.', 'neutral');
  recompute(); return true;
}
function sellAsset(id, amt){
  const d = ASSETS.find(x=>x.id===id); const h = S.assets.find(a=>a.id===id);
  if(!h) return false;
  amt = Math.min(Math.floor(amt), Math.floor(h.value));
  if(amt<=0) return false;
  const penalty = d && d.illiquid ? 0.82 : 0.99;
  const proceeds = Math.round(amt*penalty);
  h.value -= amt;
  S.fin.cash += proceeds;
  const pl = proceeds - amt;
  log('invest','Sold '+fmt(amt)+' of '+d.name+' for '+fmt(proceeds)+(d&&d.illiquid?' (illiquidity discount applied)':'')+'. P/L '+fmt(pl)+'.', pl>=0?'good':'bad');
  if(h.value < 1) S.assets = S.assets.filter(a=>a.id!==id);
  recompute(); return true;
}
function volRet(ret, vol){
  // fat tails are real, but a 6-sigma quarter turns a simulation into a lottery
  return ret + vol*clamp(R.gauss(0,1), -2.1, 2.1);
}
function stepAssets(){
  const m = S.mkt, fx = m.usd / Math.max(1, m.usdPrev);
  let income = 0;
  (S.assets||[]).forEach(a=>{
    const d = ASSETS.find(x=>x.id===a.id); if(!d) return;
    let r;
    switch(a.id){
      case 'savings': r = m.mpr/4*0.22; break;
      case 'ajo':     r = 0.026 + d.vol*clamp(R.gauss(0,1),-2.1,2.1); break;
      case 'tbill':   r = m.mpr/4*0.95; break;
      case 'fd':      r = m.mpr/4*0.88; break;
      case 'bond':    r = m.mpr/4*1.05 - 2.4*(m.mpr-(a.prevMpr||m.mpr)) + R.gauss(0,0.02); break;
      case 'ngx':     r = volRet(d.ret, d.vol) + (m.sentiment-50)/900; break;
      case 'sp500':   r = volRet(d.ret, d.vol) + (m.sentiment-50)/3500; break;
      case 'reit':    r = volRet(d.ret, d.vol) + (m.sentiment-50)/1400; break;
      case 'land':    r = volRet(d.ret, d.vol) + (m.gdp-0.03)*0.7; break;
      case 'rental':  r = volRet(d.ret, d.vol); break;
      case 'gold':    r = volRet(d.ret, d.vol) + (m.infl>0.25?0.020:0); break;
      case 'crypto':  r = volRet(d.ret, d.vol); break;
      case 'usd':     r = 0.001; break;
      default:        r = volRet(d.ret, d.vol);
    }
    a.prevMpr = m.mpr;
    r = clamp(r, -0.85, 1.20) + eraFx('ret');   // eras tilt every asset class at once
    let mult = 1 + r;
    if(d.fx) mult *= fx;
    const before = a.value;
    a.value = Math.max(0, a.value*mult);
    a.lastRet = mult - 1;
    if(d.yieldQ){ const inc = Math.round(a.value*d.yieldQ); income += inc; a.yieldAcc = (a.yieldAcc||0)+inc; }
    if(a.lastRet < -0.35) log('invest', d.name+' fell '+pct(a.lastRet,0)+' this quarter. '+fmt(a.value-before)+'.', 'bad');
    else if(a.lastRet > 0.35) log('invest', d.name+' rose '+pct(a.lastRet,0)+' this quarter. '+fmt(a.value-before)+'.', 'good');
  });
  return income;
}
function buyGood(id){
  const g = GOODS.find(x=>x.id===id); if(!g) return false;
  const cost = Math.round(g.cost * (0.85 + 0.3*CITY().rentMult/1.3));
  if(S.fin.cash < cost){ toast('You need '+fmt(cost)+'.'); return false; }
  S.fin.cash -= cost;
  S.fin.goods.push({id:id, turn:S.turn, paid:cost});
  const p = S.p;
  if(g.eff.happy) p.happy = clamp(p.happy+g.eff.happy,0,100);
  if(g.eff.stress) p.stress = clamp(p.stress+g.eff.stress,0,100);
  if(g.eff.health) p.health = clamp(p.health+g.eff.health,0,100);
  if(g.eff.rep) p.rep = clamp(p.rep+g.eff.rep,0,100);
  if(g.eff.finance) p.skills.finance = clamp(p.skills.finance+g.eff.finance,0,100);
  if(g.eff.ops) p.skills.ops = clamp(p.skills.ops+g.eff.ops,0,100);
  if(g.eff.tech) p.skills.tech = clamp(p.skills.tech+g.eff.tech,0,100);
  if(g.eff.network) p.skills.network = clamp(p.skills.network+g.eff.network,0,100);
  log('life','Bought: '+g.name+' for '+fmt(cost)+'. '+g.note, 'neutral');
  recompute(); return true;
}

/* =========================================================================
   Section 8: Consequence engine
   ========================================================================= */
function applyEff(e){
  if(!e) return;
  if(e.cash){ S.fin.cash += e.cash; tx((e.cash>0?'+':'−')+fmt(Math.abs(e.cash))); }
  if(e.usd) S.fin.usdCash = Math.max(0, S.fin.usdCash + e.usd);
  if(e.health) S.p.health = clamp(S.p.health+e.health,0,100);
  if(e.stress) S.p.stress = clamp(S.p.stress+e.stress,0,100);
  if(e.happy)  S.p.happy  = clamp(S.p.happy+e.happy,0,100);
  if(e.family) S.p.family = clamp(S.p.family+e.family,0,100);
  if(e.rep)    S.p.rep    = clamp(S.p.rep+e.rep,0,100);
  if(e.credit) S.fin.credit = clamp(S.fin.credit+e.credit,0,100);
  if(e.skill)  Object.keys(e.skill).forEach(k=>{ S.p.skills[k]=clamp(S.p.skills[k]+e.skill[k],0,100); });
  if(e.flag)   Object.keys(e.flag).forEach(k=>{ S.flags[k]=e.flag[k]; });
  if(e.informal) S.informalIncome = Math.max(0, (S.informalIncome||0) + e.informal);
  if(e.debt) S.fin.debt.push(Object.assign({id:'d'+(++S.seq), rate:0.12, minPay:0, kind:'bank'}, e.debt));
  if(e.asset){ const h=S.assets.find(a=>a.id===e.asset.id);
    if(h) h.value += e.asset.value; else S.assets.push({id:e.asset.id, value:e.asset.value, cost:e.asset.value, from:S.turn}); }
  if(e.good) S.fin.goods.push({id:e.good, turn:S.turn, paid:0});
  if(S.biz){
    const b = S.biz;
    if(e.bizcash) b.cash += e.bizcash;
    if(e.bizrep)  b.rep = clamp(b.rep+e.bizrep,0,100);
    if(e.bizcap)  b.capex += e.bizcap;
    if(e.bizqual) b.quality = clamp(b.quality+e.bizqual,0,100);
    if(e.bizloc)  { b.locations = Math.max(1, b.locations+e.bizloc); if(e.bizloc>0) b.lease.end = Math.max(b.lease.end, S.turn+8); }
    if(e.bizrecv)   b.recv = Math.max(0, (b.recv||0) + e.bizrecv);
    if(e.bizpay)    b.payable = Math.max(0, (b.payable||0) + e.bizpay);
    if(e.bizinv)    b.inventory = Math.max(0, (b.inventory||0) + e.bizinv);
    if(e.bizcomp)   b.compliance = clamp((b.compliance||40)+e.bizcomp,0,100);
    if(e.biztax)    b.taxRisk = clamp((b.taxRisk||0)+e.biztax,0,100);
    if(e.bizauto)   b.auto = clamp((b.auto||0)+e.bizauto,0,100);
    if(e.bizprod)   b.products = clamp((b.products||1)+e.bizprod,1,12);
    if(e.bizbrand)  b.brand = Math.max(0, (b.brand||0) + e.bizbrand);
    if(e.bizmorale) b.staff.forEach(function(x){ x.morale = clamp(x.morale+e.bizmorale,3,100); });
    if(e.biztrust)  b.staffTrust = clamp((b.staffTrust||55)+e.biztrust,0,100);
    if(e.bizsupp)   b.supplierConf = clamp((b.supplierConf||70)+e.bizsupp,0,100);
    if(e.bizinsure !== undefined) b.insured = !!e.bizinsure;
    if(e.bizcred !== undefined)   b.creditTerms = clamp(b.creditTerms+e.bizcred,0,1);
    if(e.bizstock !== undefined)  b.stockPolicy = clamp(b.stockPolicy+e.bizstock,0,1);
    if(e.bizkeyclient !== undefined) b.keyClient = e.bizkeyclient;
    if(e.bizcontract) { if(!b.contracts) b.contracts=[]; b.contracts.push(e.bizcontract); }
  }
  if(e.kid) S.p.kids = Math.max(0, S.p.kids + e.kid);
  if(e.marry){ S.p.married = true; S.p.partner = {name:R.pick(FIRST), income:e.marryIncome||0}; }
  if(e.job) S.p.job = e.job;
  if(e.delay) S.pending.push({turn:S.turn+e.delay.turns, title:e.delay.title, text:e.delay.text, eff:e.delay.eff, kind:e.delay.kind||'neutral'});
  if(e.log) log(e.log[0], e.log[1], e.log[2]);
}
function flushPending(){
  const due = (S.pending||[]).filter(x=>x.turn<=S.turn);
  S.pending = (S.pending||[]).filter(x=>x.turn>S.turn);
  due.forEach(p=>{
    log(p.kind==='good'?'life':(p.kind||'life'), p.title+' — '+p.text, p.kind||'neutral');
    if(p.eff) applyEff(p.eff);
  });
  return due;
}

